package extraction

import (
	"context"
	"fmt"
	"strings"

	infrallm "github.com/dnd-llm/dnd-llm/internal/infrastructure/llm"
)

// Social influence (L-layer, perception edge). A player utterance aimed at an NPC may try
// to MOVE THAT NPC'S WILL — to do or yield something it would not freely give. That pressure
// is its own ontological type, distinct from the words said (SpeechAct.Content), the deed's
// mood (modality) or a question. This narrow grammar-bound pass names the MODE of pressure
// (a closed catalog) and the STAKE (the concession sought), so the deterministic core can
// resolve compliance as a Check contest keyed by mode — never by re-reading the raw line.
//
// The MODE is the closed enum; each mode is a distinct LEVER, so it parameterizes a different
// Check (different Position/resistance): persuade leans on reason, intimidate on fear, deceive
// on a false belief, plead on mercy. «none» is the common case — most talk moves no will.

// Influence is the classifier's verdict: the mode of social pressure plus the concession sought.
type Influence struct {
	// Mode is WHICH lever the player pulls on the NPC's will (none = not an influence attempt).
	Mode string `json:"mode" enum:"none,persuade,intimidate,deceive,plead"`
	// Stake is the concession sought — what the NPC is being moved to do or give, in the
	// player's own words. Empty when Mode is none.
	Stake string `json:"stake" maxlen:"80"`
	// StakeMoney + StakeCoins carry the coin-demand verdict (DetectCoinDemand) for an intimidate
	// stake (attached after extraction, NOT part of this grammar): whether the concession is MONEY
	// (not a thing) and how many coins (0 ⇒ the whole purse). Coerced money never grounds a thing,
	// so resolveInfluence moves WEALTH when StakeMoney is set, the coerced twin of give/pickpocket.
	StakeMoney bool
	StakeCoins int
}

// Influence modes — the closed catalog of social-pressure levers (one Check parameterization each).
const (
	InfluenceNone       = "none"       // no will-moving: plain talk, a question, narration, venting, a trade offer
	InfluencePersuade   = "persuade"   // lever: reason / interest / a spoken bargain
	InfluenceIntimidate = "intimidate" // lever: threat / menace — fear of harm or loss
	InfluenceDeceive    = "deceive"    // lever: a lie / false pretense — a planted false belief
	InfluencePlead      = "plead"      // lever: mercy / pity — supplication, no leverage held
)

// Attempting reports whether the verdict is an actual influence attempt (not the common «none»).
func (in Influence) Attempting() bool { return in.Mode != "" && in.Mode != InfluenceNone }

// ClassifyInfluence reads the player's whole utterance and names the mode of social pressure
// on the addressed NPC (and the stake), over the ORIGINAL input — the lever often lives in tone
// and framing the deed segment drops. A blank mode coerces to none (the safe default: no pressure).
func ClassifyInfluence(ctx context.Context, c infrallm.SchemaCompleter, utterance string) (Influence, error) {
	req := infrallm.Request{
		SystemPrompt: influencePrompt,
		UserPrompt:   fmt.Sprintf("Сообщение игрока: «%s»\n\nОпредели режим социального влияния и ставку. Верни JSON.", utterance),
		Temperature:  0.1,
		MaxTokens:    120,
		Language:     "ru",
	}
	in, _, err := infrallm.Decode[Influence](ctx, c, req)
	if strings.TrimSpace(in.Mode) == "" {
		in.Mode = InfluenceNone
	}
	if in.Mode == InfluenceNone {
		in.Stake = "" // no concession when there is no pressure
	}
	return in, err
}

const influencePrompt = `Дано сообщение игрока, обращённое к персонажу мира. Определи, ПЫТАЕТСЯ ли игрок ДВИГАТЬ ВОЛЮ этого персонажа — склонить его сделать или отдать то, чего тот сам бы не дал, — и каким РЫЧАГОМ. JSON {"mode":"...","stake":"..."}.

Влияние есть ТОЛЬКО когда у реплики есть СТАВКА: конкретная уступка, к которой игрок клонит персонажа (пропусти, отдай, скажи, сделай, согласись, сбавь). Нет искомой уступки — нет влияния. Рычаг бывает ЯВНЫМ и НЕЯВНЫМ — читай по смыслу всей сцены, а не по одному глаголу.

Сначала спроси: добивается ли игрок УСТУПКИ — чтобы персонаж сделал, отдал или дозволил то, чего по своей воле не сделал бы (сверх простой купли-продажи товара за названную цену)? Нет искомой уступки — mode none. Есть уступка — её всегда добывают КАКИМ-ТО рычагом, и тогда реплика НЕ бывает none: назови рычаг из четырёх. Рычаг есть, даже когда он неявен — посул блага, угроза за внешне мирными словами, голая мольба о жалости тоже движут волю; не отступай в none лишь оттого, что рычаг подан тихо. Выбирай рычаг:
- persuade — рычаг РАЗУМ/ВЫГОДА/СДЕЛКА: игрок склоняет согласиться доводом, резоном ИЛИ посулом блага. Сюда же ОБМЕН-посул («сделаю/дам тебе хорошее, если уступишь») — это сделка словами, даже когда подана через «если». Доводы и посулы здесь ИСТИННЫЕ (в отличие от лжи).
- intimidate — рычаг СТРАХ/УГРОЗА: уступку вырывают, грозя персонажу вредом, болью или потерей, если он не уступит. Сама угроза и есть рычаг — будь она прямой расправой или подразумеваемой за внешне мирными словами. Например: «вернёшь монету по-доброму — или пожалеешь, что встал у меня на пути» — это intimidate. НО: брань, крик, гнев БЕЗ искомой уступки — выплеск чувства, не запугивание → none.
- deceive — рычаг ЛОЖЬ/ПРИТВОРСТВО: игрок склоняет, выдавая за правду ЗАВЕДОМО ЛОЖНОЕ — приписывает себе чужое имя или сан, ссылается на мнимого поручителя, измышляет предлог. Рычагом служит само ложное утверждение. Например: «меня послал казначей — отвори склад» (тогда как никто не посылал) — это deceive, а не persuade. Поддельный довод/предлог → deceive.
- plead — рычаг МИЛОСТЬ/ЖАЛОСТЬ: за уступкой стоит лишь чужое сострадание — игрок взывает к жалости, выставляет свою беду, просит снизойти, не предлагая выгоды и не грозя. Просьба о пощаде или снисхождении ради себя или близкого — это plead.
- none — воля персонажа не движется. Простой вопрос, рассказ, болтовня, приветствие; чистый выплеск чувства без требования; а также ТОРГ (купля-продажа за названную цену) — это коммерция, не влияние.

Различай рычаги по СМЫСЛУ: одна просьба — persuade при доводе/посуле, plead при голой мольбе о жалости, intimidate при угрозе (хоть бы и неявной), deceive при ложном основании.

stake — это ИСКОМАЯ УСТУПКА: что персонаж должен ОТДАТЬ или СДЕЛАТЬ по требованию игрока (вещь, действие, согласие). Это НЕ то, что игрок предлагает ВЗАМЕН: посул, плата, довод, угроза — РЫЧАГ, а не ставка. Например в «отдай ключ, и я тебя не трону» ставка — «ключ» (что требуют), а «не трону» — рычаг. Впиши ставку словами из сообщения; при none — stake пустой.`

package llm

import (
	"context"
	"fmt"
	"strings"

	infrallm "github.com/dnd-llm/dnd-llm/internal/infrastructure/llm"
	"go.uber.org/zap"
)

// CueClassifier answers one fuzzy perception question, grammar-bound: did the player's
// free-form deed DELIBERATELY engage one of a few authored cues at their place? Two
// subsystems ask exactly this — a story front's defuse (a lead's investigation cue) and
// a rumor hook's payoff (a rumored ritual). Both used to stem-match words, a crutch that
// trips on coincidental overlap; this is the single source of truth that replaces it, so
// "deed engages cue" can never drift between them.
//
// The verdict is BINARY (да/нет). A many-way "which cue did he engage" pick biases a 4B
// model toward choosing SOMETHING for a vague deed (measured 4/8 → false defuses); a
// reason-first yes/no is decisive (8/8). Callers with several cues that must be told
// apart loop one cue at a time and keep the first that fires.
type CueClassifier struct {
	llm    infrallm.SchemaCompleter
	logger *zap.Logger
}

// NewCueClassifier builds the classifier over a grammar-capable completer.
func NewCueClassifier(llm infrallm.SchemaCompleter, logger *zap.Logger) *CueClassifier {
	if logger == nil {
		logger = zap.NewNop()
	}
	return &CueClassifier{llm: llm, logger: logger}
}

// cueEngageSchema is the classifier's answer. The reason comes FIRST — a one-line
// articulation of WHAT the player concretely did, forcing the small model to commit to
// the facts before it judges. Then a yes/no verdict, grammar-bound to the closed enum so
// it cannot drift.
type cueEngageSchema struct {
	Reason  string `json:"reason" maxlen:"140"`
	Engaged string `json:"engaged"` // dynamic enum: да / нет
}

// The closed verdict vocabulary.
const (
	cueEngageYes = "да"
	cueEngageNo  = "нет"
)

// DeedEngages reports whether the player's free-form deed deliberately engages ANY of the
// candidate cues — perception of unstructured intent, grammar-bound so the verdict is a
// closed yes/no, never invention. The model first articulates the facts (reason), then
// judges, which keeps 4B from firing on a passive or unrelated turn. No model → false
// (callers keep a structured fallback). Decisive, not creative.
func (c *CueClassifier) DeedEngages(ctx context.Context, deed string, cues []string) bool {
	if c == nil || c.llm == nil || len(cues) == 0 || strings.TrimSpace(deed) == "" {
		return false
	}
	var listing strings.Builder
	for _, cue := range cues {
		fmt.Fprintf(&listing, "- %s\n", cue)
	}
	schema, _, err := infrallm.Decode[cueEngageSchema](ctx, c.llm, infrallm.Request{
		SystemPrompt: "Ты — строгий арбитр. Путник совершает одно действие; тебе даны конкретные дела-зацепки этого места. " +
			"Сначала в поле reason одним предложением опиши, ЧТО именно делает путник и с тем ли предметом, что в зацепке. " +
			"Затем в engaged ответь «" + cueEngageYes + "» ТОЛЬКО если путник целенаправленно занялся ровно одним из этих дел — то же ДЕЛО с тем же предметом " +
			"(разглядывать, трогать, ощупывать, исследовать названный предмет — это и есть «осмотреть» его). " +
			"ВАЖНО: предмет в зацепке тот же, но ДЕЛО должно совпасть. ПРИМЕНИТЬ предмет, пустить его в ход, действовать им " +
			"(например, поджечь факелом, ударить молотом, налить из кувшина, унести с собой) — это НЕ «осмотреть/изучить» его: осмотр — изучать, " +
			"а не использовать. Если зацепка про ОСМОТР/изучение предмета, а путник ПРИМЕНЯЕТ его или действует им — «" + cueEngageNo + "». " +
			"Если путник лишь идёт, подходит или направляется куда-то (это перемещение, а не действие над предметом), просто стоит, ждёт, " +
			"осматривается вообще по сторонам, проходит мимо или делает что-то ДРУГОЕ — «" + cueEngageNo + "».",
		UserPrompt:  fmt.Sprintf("Действие путника: «%s».\n\nДела-зацепки этого места:\n%sСначала reason, затем engaged (%s или %s). Верни JSON.", deed, listing.String(), cueEngageYes, cueEngageNo),
		Temperature: 0.1, // classification wants to be decisive, not creative
		MaxTokens:   160,
		Language:    "ru",
		Options:     &infrallm.RequestOptions{DynamicEnums: map[string][]string{"engaged": {cueEngageYes, cueEngageNo}}},
	})
	if err != nil {
		c.logger.Warn("cue-engagement classify failed", zap.Error(err))
		return false
	}
	return schema.Engaged == cueEngageYes
}

// DeedAdvancesGoal reports whether the player's deed moves an NPC's GOAL forward — the
// player-participation question (does helping count?). Unlike DeedEngages (which wants the
// deed to BE exactly a cue), this judges CONTRIBUTION: an INDIRECT but real step toward
// the aim counts (asking the right people, finding a witness, testing a hunch all advance
// an investigation), while an unrelated or obstructing deed does not. Same reason-first
// binary grammar; only the framing differs — "contributes toward" vs "is exactly". No
// model → false.
func (c *CueClassifier) DeedAdvancesGoal(ctx context.Context, deed string, aims []string) bool {
	if c == nil || c.llm == nil || len(aims) == 0 || strings.TrimSpace(deed) == "" {
		return false
	}
	var listing strings.Builder
	for _, aim := range aims {
		fmt.Fprintf(&listing, "- %s\n", aim)
	}
	schema, _, err := infrallm.Decode[cueEngageSchema](ctx, c.llm, infrallm.Request{
		SystemPrompt: "Ты — арбитр. У жителя есть ЦЕЛЬ — то, чего он добивается. Путник совершает одно действие. " +
			"Сначала в reason одним предложением опиши, ЧТО делает путник и КАК это относится к цели. " +
			"Затем в engaged ответь «" + cueEngageYes + "», если действие ПРОДВИГАЕТ достижение цели хоть на шаг — собирает нужные сведения, " +
			"находит свидетельство, устраняет препятствие, делает вклад. КОСВЕННЫЙ, но осмысленный вклад засчитывается: " +
			"расспросить нужных людей, поискать улики, проверить догадку — всё это продвигает расследование, даже если цель ещё не достигнута. " +
			"Но вклад должен быть НАПРАВЛЕН на предмет цели — на её вопрос, лицо или место. " +
			"Ответь «" + cueEngageNo + "», если действие никак не относится к цели, путник просто стоит/занят своим, или МЕШАЕТ цели — " +
			"а также если действие ОБЩЕЕ, ни на что конкретно по цели не нацеленное, лишь оказавшееся рядом с темой (праздный взгляд по сторонам, своё обыденное дело).",
		UserPrompt:  fmt.Sprintf("Цель жителя:\n%sДействие путника: «%s».\n\nПродвигает ли это действие достижение цели? Сначала reason, затем engaged (%s или %s). Верни JSON.", listing.String(), deed, cueEngageYes, cueEngageNo),
		Temperature: 0.1,
		MaxTokens:   160,
		Language:    "ru",
		Options:     &infrallm.RequestOptions{DynamicEnums: map[string][]string{"engaged": {cueEngageYes, cueEngageNo}}},
	})
	if err != nil {
		c.logger.Warn("goal-advance classify failed", zap.Error(err))
		return false
	}
	return schema.Engaged == cueEngageYes
}

