package llm

import (
	"context"
	"fmt"
	"strings"

	"github.com/dnd-llm/dnd-llm/internal/domain/entity"
	infrallm "github.com/dnd-llm/dnd-llm/internal/infrastructure/llm"
)

// The effect classifier is the consequence-sensor: given the player's DEED, it picks
// — under a grammar — which transformation from the closed catalogue the ACTION
// produces. It runs in TWO narrow layers (one job per call, the parser's discipline):
//
//   1. DOMAIN — the KIND of influence (разрушение / жар / влага / поверхность /
//      содержимое / положение / никакой). A coarse six-way choice.
//   2. LEAF — the specific effect WITHIN that domain, chosen from that domain's
//      effects ALONE.
//
// Why split: one flat 23-way choice crowded six «о»-effects together and lost a
// direct verb across domains («отмыть грязный котелок» → «опрокинуть»). The leaf layer
// only ever sees its own domain's effects, so a cross-domain slip is physically
// impossible. The hard seam the 4B reveals is NOUN-ANCHORING — it reaches for the
// effect that suits the OBJECT (a pot → tip it / empty it) instead of the VERB; both
// layers fight it by naming the verb-focus rule and (the domain layer) held-out
// examples. WHICH thing is affected is grounded deterministically elsewhere, by name;
// the verdict's RefineForce/RefineHeat then settle the exact leaf by the thing's
// material, so within a physical domain the leaf here is only ever coarse.
//
// BOUNDARY (see ai-docs/concept/22-deed-routing.md): this sensor is reached ONLY via
// the `other` action kind. observe/talk/move/take/give/attack are routed away by the
// parser's kind-layer and NEVER arrive — so the prompt must NOT teach «look»/«examine»
// (a layer it does not own). «никакой» here is the narrow residual of an `other` deed
// that CONTACTS a thing but transforms nothing (погладить/потрогать), not look/talk.

// effectNone is the sentinel: the deed changes no thing (a touch that leaves no mark).
const effectNone = "никакой"

type effectDomainSchema struct {
	Domain string `json:"domain"` // dynamic enum: influence domains + effectNone
}

type effectSelectSchema struct {
	Effect string `json:"effect"` // dynamic enum: one domain's leaves
}

// EffectSelector classifies a deed into a catalogue effect through the two layers.
type EffectSelector struct {
	llm infrallm.SchemaCompleter
}

// NewEffectSelector builds a classifier. A nil completer makes Classify return
// "" — the deed changes nothing.
func NewEffectSelector(llm infrallm.SchemaCompleter) *EffectSelector {
	return &EffectSelector{llm: llm}
}

// Classify returns the catalogue effect the deed produces, or "" for «никакой».
// Grammar-bound to the catalogue; the verdict engine owns the mechanics and grounds
// WHICH thing is affected itself. Two grammar-bound calls: domain, then leaf — a
// single-leaf domain (положение → опрокинуть) skips the second call.
func (s *EffectSelector) Classify(ctx context.Context, deed string) (string, error) {
	if s == nil || s.llm == nil || strings.TrimSpace(deed) == "" {
		return "", nil
	}
	domain, err := s.ClassifyDomain(ctx, deed)
	if err != nil || domain == "" {
		return "", err
	}
	leaves := entity.EffectsInDomain(domain)
	if len(leaves) == 0 {
		return "", nil // unknown domain (the grammar prevents this, but stay safe)
	}
	return s.classifyLeaf(ctx, deed, domain, leaves)
}

// ClassifyDomain picks the KIND of influence the deed applies — one of the six real
// domains. There is NO «никакой» domain: a no-change contact deed (погладить/потрогать)
// is forced into its closest domain here and the LEAF layer answers «никакой», exactly
// as the flat classifier did — concrete-effect matching is what robustly recognises «no
// effect», not an abstract domain (the «поверхность» domain is a loose attractor for any
// touch, so a «никакой» domain LOST the cases the leaf layer keeps). Exported as the
// first layer's entry point so an isolated bench can exercise it directly.
func (s *EffectSelector) ClassifyDomain(ctx context.Context, deed string) (string, error) {
	if s == nil || s.llm == nil || strings.TrimSpace(deed) == "" {
		return "", nil
	}
	schema, _, err := infrallm.Decode[effectDomainSchema](ctx, s.llm, infrallm.Request{
		SystemPrompt: effectDomainSystem,
		UserPrompt:   fmt.Sprintf("Действие игрока: %s\n\nКакого рода это воздействие? Верни JSON.", deed),
		Temperature:  0.2,
		MaxTokens:    32,
		Language:     "ru",
		Options:      &infrallm.RequestOptions{DynamicEnums: map[string][]string{"domain": entity.EffectDomains()}},
	})
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(schema.Domain), nil
}

// classifyLeaf picks the specific effect WITHIN an already-chosen domain, OR «никакой»
// when no concrete effect of that domain actually fits (a touch that contacts but
// transforms nothing). It frames the choice by RESULT (the same shift that fixed the
// domain layer): each candidate is shown with its catalogue Note — the END STATE it
// leaves — so the model matches the deed's INTENDED outcome («отмыть грязный котелок»
// → end state «чистое» → отмыть) instead of grabbing an «о»-sibling on the «грязный»
// distractor. When the deed's outcome matches NO end state (mere contact), «никакой».
// Returns "" for the «никакой» case.
func (s *EffectSelector) classifyLeaf(ctx context.Context, deed, domain string, leaves []string) (string, error) {
	enum := append(append([]string(nil), leaves...), effectNone)
	var glosses strings.Builder
	for _, k := range leaves {
		if note := entity.EffectNote(k); note != "" {
			fmt.Fprintf(&glosses, "- %s → итог: %s\n", k, note)
		} else {
			fmt.Fprintf(&glosses, "- %s\n", k)
		}
	}
	schema, _, err := infrallm.Decode[effectSelectSchema](ctx, s.llm, infrallm.Request{
		SystemPrompt: effectLeafSystem,
		UserPrompt: fmt.Sprintf(
			"Действие игрока: %s\nРод воздействия: %s\n\nЭффекты этого рода и их ИТОГ для вещи:\n%s\nВыбери эффект, чей ИТОГ наступает от действия игрока. Если действие лишь касается вещи и НИ ОДИН из этих итогов не наступает — «%s». Верни JSON.",
			deed, domain, glosses.String(), effectNone),
		Temperature: 0.2,
		MaxTokens:   32,
		Language:    "ru",
		Options:     &infrallm.RequestOptions{DynamicEnums: map[string][]string{"effect": enum}},
	})
	if err != nil {
		return "", err
	}
	if e := strings.TrimSpace(schema.Effect); e != effectNone {
		return e, nil
	}
	return "", nil
}

// The domain prompt fights NOUN-ANCHORING head-on (the seam the 4B reveals): it names
// the verb-focus rule first, narrows the soft domains (содержимое is ONLY pour-in/out),
// and frames each domain by the END STATE of the thing (not its current look or a
// salient noun). NO few-shot examples: an earlier set leaked — they were paraphrases of
// the bench cases (a removal-test exposed +5 inflated points), so the layer teaches by
// DEFINITION only, and the leaf carries the closed catalogue Notes as result-glosses.
const effectDomainSystem = `Ты — сенсор последствий в игровом движке. Тебе дают ДЕЙСТВИЕ игрока над вещью. Назови РОД воздействия — что действие делает с вещью.

Смотри на ГЛАГОЛ (что игрок ДЕЛАЕТ), а НЕ на предмет: один и тот же предмет можно ломать, чистить, наполнять или ронять — род задаёт действие, не вещь.

Гляди на КОНЕЧНОЕ состояние вещи — каким оно стало:
- разрушение — вещь сломана, погнута, порвана, проткнута, смята.
- жар — вещь горит, оплавилась, ЛИБО на ней погасили огонь (итог для огня важнее средства: чем бы ни гасили).
- влага — вещь стала МОКРОЙ (на неё плеснули или налили ЛЮБУЮ жидкость — воду, вино, масло, молоко), мёрзлой или сухой. Это про сырость, не про стойкий налёт. НО если на вещи был ОГОНЬ и его этой жидкостью ПОГАСИЛИ — род жар (тушение), а не влага: итог для огня важнее того, что мокро.
- поверхность — на вещи появился или сошёл СТОЙКИЙ слой: грязь, копоть, краска, кровь — её пачкают, отчищают дочиста или красят. Форма цела. (Чистка — сюда: итог — чистая вещь, а вода лишь средство.)
- содержимое — ВНУТРИ сосуда жидкости стало больше или меньше: в него налили или из него вылили. НЕ когда плещут жидкость НА вещь снаружи.
