Даже если вещь лишь тронули и ничего не изменилось — всё равно назови БЛИЖАЙШИЙ род по тому, к чему игрок тянется (потом уточнится, что эффекта нет).`

const effectLeafSystem = `Ты — сенсор последствий. Род воздействия уже определён; тебе дают его эффекты вместе с ИТОГОМ, который каждый оставляет на вещи. Выбери эффект, чей итог наступает от действия игрока. Смотри на то, каким станет КОНЕЧНОЕ состояние вещи, а не на её нынешний вид и не на отдельные слова реплики. Лёгкое касание, поглаживание или опора сами по себе НИ ОДНОГО из этих итогов не дают (итог требует настоящего воздействия, а не простого прикосновения) — тогда «никакой».`

package entity

import "sort"

// Effects are the closed catalogue of transformations a thing of the world can
// undergo. The catalogue is the SINGLE SOURCE OF TRUTH: the sensor selects an
// effect from it under a grammar (it physically cannot emit one that is not
// here), the choice is journaled, and each effect's mechanics — its committed
// condition, its fact sentence, whether it leaves a standing hazard, what means
// it needs — are DETERMINISTIC and live right here. This is the
// deterministic-core contract: the LLM classifies (which of these closed
// outcomes fits), the core computes (the outcome is fixed per key). Replaying
// the log re-applies the same mechanics from the journaled key — no LLM in the
// replay path. Open-endedness comes from a LARGE catalogue, not from free-form
// generation. Grow it by adding one row with its properties.

// Means an effect may require — a closed vocabulary the verdict engine checks
// against the instrument at hand (honest "нечем" when the means is absent).
const (
	MeansNone  = ""      // bare hands suffice
	MeansFire  = "огонь" // needs a flame / heat source (carried to the target)
	MeansWater = "вода"  // needs a water source (a river, a well, a barrel — splashed, not carried)
)

// IsMeans reports whether a value names a real elemental means — the shared
// vocabulary of the source axis (what a thing SUPPLIES, entity.SetSource) and an
// effect's requirement (what it NEEDS, Effect.Requires). MeansNone is not a means.
func IsMeans(s string) bool { return s == MeansFire || s == MeansWater }

// Effect keys are Russian infinitives — the grammar enum value AND the journaled
// key (events already carry Russian text; the morphology contract holds because
// the key never inflects, only the fact's gender-neutral verb does).
const (
	EffectBurn      = "поджечь"
	EffectChar      = "обуглить"
	EffectMelt      = "растопить"
	EffectExtingush = "потушить"
	EffectShatter   = "разбить"
	EffectBreak     = "сломать"
	EffectCrack     = "расколоть"
	EffectCrush     = "раздавить"
	EffectBend      = "погнуть"
	EffectPierce    = "проткнуть"
	EffectScratch   = "поцарапать"
	EffectTear      = "порвать"
	EffectCrumple   = "смять"
	EffectSoak      = "облить"
	EffectDry       = "высушить"
	EffectFreeze    = "заморозить"
	EffectStain     = "испачкать"
	EffectClean     = "отмыть"
	EffectPaint     = "покрасить"
	EffectTopple    = "опрокинуть"
	EffectFill      = "наполнить"
	EffectEmpty     = "опустошить"
	EffectBloody    = "окровавить"
)

// Effect is one entry of the catalogue.
type Effect struct {
	Key string
	// Fact is the deterministic outcome sentence with ONE %s for the entity's
	// name in the nominative. The verb is gender-neutral (3rd-person singular
	// present: «загорается», «трескается») so the name slots in without
	// agreement — the morphology contract.
	Fact string
	// Note is the committed condition text written onto the entity (closed
	// vocabulary; carried into knowledge packs so the world remembers).
	Note string
	// Hazard marks an effect that leaves a STANDING environmental threat (fire
	// keeps burning, endangers everyone present) — the tick floors fear on the
	// co-located so a burning place empties out.
	Hazard bool
	// Requires is the means the effect needs, or MeansNone. The verdict engine
	// refuses the deed honestly when the means is absent (unless MeansOptional).
	Requires string
	// MeansOptional marks an effect whose Requires means ENRICHES the outcome but is
	// not mandatory — the influence is achievable by an alternate means too. Putting
	// out a fire is the prototype: water (the means) leaves the thing wet and raises
	// steam, but smothering it (no water at hand) still works, leaving it merely cooled.
	// When the means is absent, the verdict proceeds with FactNoMeans instead of fizzling,
	// and the mutator skips the means' signature (the wetting). A hard-required means
	// (fire to ignite) is impotent when absent; an optional one only changes the outcome.
	MeansOptional bool
	// FactNoMeans is the outcome sentence for a MeansOptional effect performed WITHOUT
	// its means (the smother variant of extinguishing) — same one %s for the name. Empty
	// for effects whose means is mandatory (Fact always applies).
	FactNoMeans string
	// RequiresHazard marks an effect that only bites a thing CURRENTLY a standing
	// hazard — you cannot put out what is not alight. The verdict engine treats it
	// as impotent against a thing with no StateHazard, so it never overwrites a
	// settled condition (a charred ruin stays charred, not "extinguished").
	RequiresHazard bool
	// RequiresFlammable marks a catch-fire effect (burn, char) that only bites a
	// thing whose MATERIAL catches — the same per-thing judgment the spread uses
	// (Entity.CatchesFire). The verdict treats it as impotent against an
	// unflammable thing, so arson and spread share ONE flammability gate: a wooden
	// hut burns, a river or a clay mug does not, and ash never reignites.
	RequiresFlammable bool
	// RequiresFusible marks a MELT effect that only bites a thing whose THERMAL
	// response is FUSIBLE (плавится) — the heat twin of RequiresFlammable. The
	// verdict treats it as impotent against a thing that does not melt, so «растопить
	// камень факелом» fizzles: heat may char or do nothing, but stone never melts to
	// liquid. The affordance and the gate are one axis (thermal), as for fracture.
	RequiresFusible bool
	// RequiresVessel marks a CONTENTS effect (fill, empty) that only bites a thing whose
	// liquid FORM is a сосуд — a cavity that holds liquid. The verdict treats it as
	// impotent against a non-vessel, so «наполнить меч водой» fizzles: a blade has no
	// cavity to fill. The liquid-domain twin of RequiresFlammable/RequiresFusible.
	RequiresVessel bool
	// RequiresFull marks an effect (empty) that needs a vessel CURRENTLY holding liquid
	// — you cannot pour out an already-empty cup.
	RequiresFull bool
	// Content, when set, is the CONTENTS state this effect leaves: ContentFull (the
	// vessel is now full) or ContentEmpty (poured out). Empty leaves contents unchanged.
	Content string
	// ClearsHazard marks an effect that ENDS a standing hazard (extinguishing a
	// fire): the mutator drops the hazard markers, so the thing stops burning,
	// spreading and flooring fear. This is how a player fights a fire — the
	// counterpart to the tick's BurnOut, but the thing survives scorched, not
	// consumed.
	ClearsHazard bool
	// Integrity is the STRUCTURAL toll this effect inflicts — the level the thing's
	// condition is raised to (monotonically). IntegrityIntact (the zero value) means
	// no structural harm (a stain, a topple, a dousing): the thing is marked, not
	// weakened. Damaged things still function (a charred frame stands); Ruined ones
	// do not (shards, rubble). The world keys consequences to the level.
	Integrity Integrity
	// Moisture, when set, is the MOISTURE state this effect leaves: MoistureWet (the
	// thing is now wet — dousing, extinguishing-with-water) or MoistureDry (dried out).
	// Empty leaves moisture unchanged. Wet suppresses CatchesFire — water beats fire —
	// so a doused thing resists the spreading blaze until it dries (see moisture.go).
	Moisture string
	// Phase, when set, is the new physical FORM this effect leaves — the thing's
	// affordances (thermal, fracture) are RE-DERIVED to it, because they are properties
	// of a thing's STATE and this effect changed the state. Melting leaves a formless
	// puddle (heat-inert, no fracture); most effects change a thing's condition without
	// changing its form (a stain, a dent), so they leave Phase nil. The transition is
	// UNCONDITIONAL given the effect applied — its affordance gate (fusible for melt)
	// already ensured the effect only reaches a thing the transition suits.
	Phase *PhaseShift
}

// PhaseShift is the physical FORM a transforming effect leaves: the thermal response
// and fracture mode the thing has AFTER it. An empty axis means the new form has no
// response there (a formless puddle has no fracture), and ShiftPhase clears it.
type PhaseShift struct {
	Thermal  string
	Fracture string
}

// effects is the catalogue. Adding an effect here is the ONLY place its
// properties live; the sensor's enum and the verdict's mechanics both read it.
var effects = map[string]Effect{
	EffectBurn:      {Key: EffectBurn, Fact: "Огонь занялся: %s загорается.", Note: "охвачено огнём: чернеет и тлеет", Hazard: true, Requires: MeansFire, RequiresFlammable: true, Integrity: IntegrityDamaged},
	EffectChar:      {Key: EffectChar, Fact: "Жар безжалостен: %s обугливается.", Note: "обуглено: почернело и потрескалось", Hazard: true, Requires: MeansFire, RequiresFlammable: true, Integrity: IntegrityDamaged},
	EffectMelt:      {Key: EffectMelt, Fact: "Под жаром: %s оплывает.", Note: "оплавлено, потеряло форму", Requires: MeansFire, RequiresFusible: true, Integrity: IntegrityDamaged, Phase: &PhaseShift{Thermal: ThermalInert}},
	EffectExtingush: {Key: EffectExtingush, Fact: "Вода с шипением обращается в пар: %s гаснет.", FactNoMeans: "Ты сбиваешь пламя: %s гаснет, остывая.", Note: "потушено, ещё дымится", RequiresHazard: true, ClearsHazard: true, Requires: MeansWater, MeansOptional: true, Moisture: MoistureWet},
	EffectShatter:   {Key: EffectShatter, Fact: "Вдребезги: %s разлетается осколками.", Note: "разбито: осколки повсюду", Integrity: IntegrityRuined},
	EffectBreak:     {Key: EffectBreak, Fact: "Не выдерживает: %s трещит и ломается.", Note: "сломано: трещины и щепа", Integrity: IntegrityRuined},
	EffectCrack:     {Key: EffectCrack, Fact: "С хрустом: %s раскалывается.", Note: "расколото надвое", Integrity: IntegrityRuined},
	EffectCrush:     {Key: EffectCrush, Fact: "Под нажимом: %s сминается всмятку.", Note: "раздавлено, бесформенно", Integrity: IntegrityRuined},
	EffectBend:      {Key: EffectBend, Fact: "С натугой: %s гнётся.", Note: "погнуто, перекошено", Integrity: IntegrityDamaged},
	EffectPierce:    {Key: EffectPierce, Fact: "Насквозь: %s протыкается.", Note: "проткнуто, с дырой", Integrity: IntegrityDamaged},
	EffectScratch:   {Key: EffectScratch, Fact: "След остаётся: %s покрывается царапинами.", Note: "исцарапано"},
	EffectTear:      {Key: EffectTear, Fact: "С треском: %s рвётся.", Note: "порвано, в клочья", Integrity: IntegrityRuined},
	EffectCrumple:   {Key: EffectCrumple, Fact: "В комок: %s комкается.", Note: "смято, в складках", Integrity: IntegrityDamaged},
	EffectSoak:      {Key: EffectSoak, Fact: "Вода повсюду: %s промокает насквозь.", Note: "вымокло, с него течёт", Requires: MeansWater, Moisture: MoistureWet},
	EffectDry:       {Key: EffectDry, Fact: "Ни капли: %s высыхает.", Note: "высушено", Moisture: MoistureDry},
	EffectFreeze:    {Key: EffectFreeze, Fact: "Стужа сковывает: %s покрывается коркой льда.", Note: "сковано льдом"},
	EffectStain:     {Key: EffectStain, Fact: "Грязь ложится: %s покрывается разводами.", Note: "испачкано, в разводах"},
	EffectClean:     {Key: EffectClean, Fact: "Дочиста: %s отмывается.", Note: "отмыто, чистое"},
	EffectPaint:     {Key: EffectPaint, Fact: "Свежий слой: %s покрывается краской.", Note: "окрашено"},
	EffectTopple:    {Key: EffectTopple, Fact: "С грохотом: %s опрокидывается набок.", Note: "опрокинуто, лежит на боку"},
	EffectFill:      {Key: EffectFill, Fact: "До краёв: %s наполняется.", Note: "наполнено", RequiresVessel: true, Requires: MeansWater, Content: ContentFull},
	EffectEmpty:     {Key: EffectEmpty, Fact: "До дна: %s пустеет.", Note: "опустошено", RequiresVessel: true, RequiresFull: true, Content: ContentEmpty},
	EffectBloody:    {Key: EffectBloody, Fact: "Багровые следы: %s покрывается кровью.", Note: "в кровавых разводах"},
}

// Effects cluster into INFLUENCE DOMAINS — the KIND of influence a deed applies. This
// is the same ontology the affordance axes follow (force→fracture, heat→thermal,
// contents→containment): the consequence sensor classifies the DOMAIN first (a coarse,
// reliable choice among six) and then the leaf WITHIN it (a small, uncrowded choice),
// so a deed is never lost ACROSS domains — washing a pot is surface-work, never
// confused with tipping it over, because the leaf for «отмыть» is chosen from
// {испачкать, отмыть, покрасить, окровавить} alone.
const (
	DomainForce    = "разрушение"  // mechanical force: shatter, break, tear, bend…
	DomainHeat     = "жар"         // heat & fire: burn, char, melt, extinguish
	DomainMoisture = "влага"       // water, ice, drying: douse, freeze, dry
	DomainSurface  = "поверхность" // marking the surface, form unchanged: stain, clean, paint, bloody
	DomainContents = "содержимое"  // the contents of a vessel: fill, empty
	DomainPosition = "положение"   // orientation in space: topple
)

// effectDomains partitions the catalogue: every effect belongs to EXACTLY ONE domain
// (guarded by a test). This is the single source the two-layer sensor reads — the
// domain enum and each domain's leaf enum both derive from it.
var effectDomains = map[string][]string{
	DomainForce:    {EffectShatter, EffectBreak, EffectCrack, EffectCrush, EffectBend, EffectPierce, EffectScratch, EffectTear, EffectCrumple},
	DomainHeat:     {EffectBurn, EffectChar, EffectMelt, EffectExtingush},
	DomainMoisture: {EffectSoak, EffectDry, EffectFreeze},
	DomainSurface:  {EffectStain, EffectClean, EffectPaint, EffectBloody},
	DomainContents: {EffectFill, EffectEmpty},
	DomainPosition: {EffectTopple},
}

// domainOf is the reverse index (leaf → its domain), built once from effectDomains.
var domainOf = func() map[string]string {
	m := make(map[string]string, len(effects))
	for d, leaves := range effectDomains {
		for _, leaf := range leaves {
			m[leaf] = d
		}
	}
	return m
}()

// EffectDomains returns every influence domain in a stable order — the sensor's
// first-layer (coarse) grammar enum.
func EffectDomains() []string {
	ds := make([]string, 0, len(effectDomains))
	for d := range effectDomains {
		ds = append(ds, d)
	}
	sort.Strings(ds)
	return ds
}

// EffectsInDomain returns the catalogue effects of one domain in a stable order — the
// sensor's second-layer grammar enum, restricted so a leaf from another domain is
// physically unpickable.
func EffectsInDomain(domain string) []string {
	leaves := append([]string(nil), effectDomains[domain]...)
	sort.Strings(leaves)
	return leaves
}

// DomainOf returns the influence domain an effect belongs to, or "" if unknown.
func DomainOf(effect string) string { return domainOf[effect] }

// EffectFor returns the catalogue entry for a key and whether it is known.
func EffectFor(key string) (Effect, bool) {
	e, ok := effects[key]
	return e, ok
}

// EffectNote returns an effect's committed condition text, or "" for unknown.
func EffectNote(key string) string { return effects[key].Note }

// IsHazardEffect reports whether an effect leaves a standing environmental
// hazard (so the tick keeps flooring fear on everyone present).
func IsHazardEffect(key string) bool { return effects[key].Hazard }

// EffectNeedsHazard reports whether an effect only applies to a thing that is
// currently a standing hazard (e.g. extinguishing needs an active fire).
func EffectNeedsHazard(key string) bool { return effects[key].RequiresHazard }

// EffectNeedsFlammable reports whether an effect only applies to a thing whose
// material catches fire (burn, char) — the verdict gates it on Entity.CatchesFire.
func EffectNeedsFlammable(key string) bool { return effects[key].RequiresFlammable }

// EffectNeedsFusible reports whether an effect only applies to a thing that MELTS
// under heat (растопить) — the verdict gates it on the thing's thermal response,
// the heat twin of EffectNeedsFlammable.
func EffectNeedsFusible(key string) bool { return effects[key].RequiresFusible }

// EffectClearsHazard reports whether an effect ends a standing hazard (e.g.
// extinguishing a fire) — the mutator drops the hazard markers when it applies.
func EffectClearsHazard(key string) bool { return effects[key].ClearsHazard }

// EffectRequires returns the means an effect needs (MeansFire/MeansWater/MeansNone) —
// the means side of the catalogue, also the liquid a fill leaves in a vessel.
func EffectRequires(key string) string { return effects[key].Requires }

// EffectMeansOptional reports whether an effect's required means only ENRICHES the
// outcome (water for extinguishing) rather than being mandatory — the verdict
// proceeds with FactNoMeans when it is absent instead of fizzling.
func EffectMeansOptional(key string) bool { return effects[key].MeansOptional }

// EffectFactNoMeans returns the outcome sentence for a MeansOptional effect done
// without its means (the smother variant), or "" when the means is mandatory.
func EffectFactNoMeans(key string) string { return effects[key].FactNoMeans }

// EffectIntegrity reports the structural condition an effect inflicts — the level a
// thing's integrity is raised to (IntegrityIntact for a purely cosmetic effect).
func EffectIntegrity(key string) Integrity { return effects[key].Integrity }

// EffectPhaseShift reports the new physical FORM an effect leaves (its re-derived
// affordances), or nil for an effect that does not change a thing's form.
func EffectPhaseShift(key string) *PhaseShift { return effects[key].Phase }

// EffectMoisture reports the moisture state an effect leaves (MoistureWet/MoistureDry),
// or "" for an effect that does not change a thing's wetness.
func EffectMoisture(key string) string { return effects[key].Moisture }

// EffectNeedsVessel reports whether an effect only applies to a сосуд (fill, empty) —
// the verdict gates it on Entity.IsVessel.
func EffectNeedsVessel(key string) bool { return effects[key].RequiresVessel }

// EffectNeedsFull reports whether an effect needs a vessel currently holding liquid
// (empty) — gated on Entity.IsFull.
func EffectNeedsFull(key string) bool { return effects[key].RequiresFull }

// EffectContent reports the contents state an effect leaves (ContentFull/ContentEmpty),
// or "" for an effect that does not change a vessel's contents.
func EffectContent(key string) string { return effects[key].Content }

// EffectKeys returns all catalogue keys in a stable order — the sensor's
// grammar enum.
func EffectKeys() []string {
	keys := make([]string, 0, len(effects))
	for k := range effects {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

