func runDomain(ctx context.Context, p infrallm.SchemaCompleter, samples int, only string) {
	parser := extraction.NewIntentParser(p)
	for i, c := range domainCases {
		if only != "" && !strings.Contains(c.phrase, only) && !strings.Contains(c.field, only) {
			continue
		}
		conv := ""
		if c.inConv {
			conv = " (в разговоре)"
		}
		fmt.Printf("\n%s\n#%-2d [%s=%s]%s  «%s»\n%s\n",
			strings.Repeat("═", 90), i+1, c.field, c.want, conv, c.phrase, strings.Repeat("─", 90))
		pc := extraction.ParseContext{InConversation: c.inConv}
		if c.merchant {
			pc.Affordances = merchantAffords
		}
		for s := 1; s <= samples; s++ {
			pt, _, err := parser.Parse(ctx, c.phrase, pc)
			if err != nil {
				fmt.Printf("  ⃟%d ✗ %v\n", s, err)
				continue
			}
			var got string
			switch c.field {
			case "count": // number of deeds the message segmented into (merge / phantom regressions)
				got = strconv.Itoa(len(pt.Actions))
			case "modality": // the deed's envelope — scan for a non-default value
				got = extraction.ModalityActual
				for _, a := range pt.Actions {
					if a.Modality != "" && a.Modality != extraction.ModalityActual {
						got = a.Modality
						break
					}
				}
			default: // take the field from the action that carries it (first non-empty), else action[0]
				for _, a := range pt.Actions {
					if v := domainField(a, c.field); v != "" && v != "false" {
						got = v
						break
					}
				}
				if got == "" && len(pt.Actions) > 0 {
					got = domainField(pt.Actions[0], c.field)
				}
			}
			mark := "✓"
			if got != c.want {
				mark = "✗"
			}
			fmt.Printf("  ⃟%d  %s  %s\n", s, got, mark)
		}
	}
}

