// Package dbjson provides strictly-typed JSON column wrappers. A JSON column is TEXT holding
// JSON; database/sql cannot (un)marshal a domain value across that boundary on its own, so the
// column field would otherwise be opaque []byte (json.RawMessage) that every reader must
// json.Unmarshal by hand — losing the type at the persistence edge. These generic wrappers carry
// the (un)marshal + NULL handling once, so a column field IS its concrete domain type T: the
// compiler enforces the shape and callers never touch bytes.
package dbjson

import (
	"database/sql/driver"
	"encoding/json"
	"fmt"
)

// JSON wraps a concrete value T stored in a NOT NULL JSON column. Scan/Value (un)marshal T at the
// database boundary; an empty/absent payload decodes to T's zero value (a NOT NULL column never
// holds SQL NULL, so Value always emits JSON, never NULL).
type JSON[T any] struct {
	V T
}

// Scan implements sql.Scanner: JSON text/blob → T (empty → zero T).
func (j *JSON[T]) Scan(src any) error {
	b, err := bytesOf(src)
	if err != nil {
		return err
	}
	if len(b) == 0 {
		var zero T
		j.V = zero
		return nil
	}
	return json.Unmarshal(b, &j.V)
}

// Value implements driver.Valuer: T → JSON bytes (never SQL NULL).
func (j JSON[T]) Value() (driver.Value, error) {
	return json.Marshal(j.V)
}

// Null wraps a concrete value T stored in a NULLABLE JSON column. SQL NULL ⇄ Valid=false, so
// "absent" is a first-class READable state (the pure-Go SQLite driver hands back NULL as a nil
// driver.Value), not something writers must conspire to avoid producing.
type Null[T any] struct {
	V     T
	Valid bool
}

// Scan implements sql.Scanner: NULL/empty → Valid=false, JSON text/blob → T with Valid=true.
func (n *Null[T]) Scan(src any) error {
	b, err := bytesOf(src)
	if err != nil {
		return err
	}
	if len(b) == 0 {
		var zero T
		n.V, n.Valid = zero, false
		return nil
	}
	n.Valid = true
	return json.Unmarshal(b, &n.V)
}

// Value implements driver.Valuer: Valid → JSON bytes, else SQL NULL.
func (n Null[T]) Value() (driver.Value, error) {
	if !n.Valid {
		return nil, nil
	}
	return json.Marshal(n.V)
}

func bytesOf(src any) ([]byte, error) {
	switch v := src.(type) {
	case nil:
		return nil, nil
	case []byte:
		return v, nil
	case string:
		return []byte(v), nil
	default:
		return nil, fmt.Errorf("dbjson: cannot scan %T into a JSON column", src)
	}
}

