package db

import (
	"context"
	"path/filepath"
	"testing"
)

// TestApplyBaseline is the Stage-1 verification: the consolidated baseline
// migration applies cleanly to a fresh Turso file, is idempotent, creates the
// expected tables, supports the INSERT ... RETURNING the relational layer needs,
// and enforces the ON DELETE CASCADE the reseed/teardown paths depend on.
func TestApplyBaseline(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "test.db")

	database, err := Open(ctx, path, 0)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer database.Close()

	applied, err := Apply(ctx, database)
	if err != nil {
		t.Fatalf("apply: %v", err)
	}
	if len(applied) != 2 || applied[0] != 1 || applied[1] != 2 {
		t.Fatalf("expected to apply [1 2], got %v", applied)
	}

	// Idempotent: a second Apply is a no-op.
	again, err := Apply(ctx, database)
	if err != nil {
		t.Fatalf("re-apply: %v", err)
	}
	if len(again) != 0 {
		t.Fatalf("expected no migrations on re-apply, got %v", again)
	}

	if v, err := CurrentVersion(ctx, database); err != nil || v != 2 {
		t.Fatalf("version = %d, err = %v; want 2", v, err)
	}

	// Every table the stores read/write must exist.
	wantTables := []string{
		"users", "worlds", "locations", "actors", "items", "events",
		"event_streams", "event_connections", "snapshots", "sessions",
		"characters", "player_groups", "group_members", "resource_locks",
		"group_visibility", "event_conflicts", "sync_points", "worldgen_jobs",
		"entities", "entity_links", "name_morphology", "entity_embeddings",
		"memory_embeddings", "graph_nodes", "graph_edges",
	}
	for _, tbl := range wantTables {
		var name string
		err := database.QueryRowContext(ctx,
			`SELECT name FROM sqlite_master WHERE type='table' AND name=?`, tbl).Scan(&name)
		if err != nil {
			t.Errorf("table %q missing: %v", tbl, err)
		}
	}

	// INSERT ... RETURNING round-trip (sqlc :one pattern).
	var gotID string
	err = database.QueryRowContext(ctx,
		`INSERT INTO worlds (id, name, status) VALUES (?, ?, 'active') RETURNING id`,
		"w1", "Заречье").Scan(&gotID)
	if err != nil || gotID != "w1" {
		t.Fatalf("insert world RETURNING: id=%q err=%v", gotID, err)
	}

	// ON DELETE CASCADE: a location under the world must vanish with it.
	if _, err := database.ExecContext(ctx,
		`INSERT INTO locations (id, world_id, name, location_type) VALUES ('l1','w1','Караульня','room')`); err != nil {
		t.Fatalf("insert location: %v", err)
	}
	if _, err := database.ExecContext(ctx, `DELETE FROM worlds WHERE id='w1'`); err != nil {
		t.Fatalf("delete world: %v", err)
	}
	var locCount int
	if err := database.QueryRowContext(ctx, `SELECT COUNT(*) FROM locations`).Scan(&locCount); err != nil {
		t.Fatalf("count locations: %v", err)
	}
	if locCount != 0 {
		t.Fatalf("ON DELETE CASCADE did not reap location: %d left", locCount)
	}
}

// TestRollbackBaseline verifies the down migration drops the schema and version
// returns to 0.
func TestRollbackBaseline(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "test.db")

	database, err := Open(ctx, path, 0)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer database.Close()

	if _, err := Apply(ctx, database); err != nil {
		t.Fatalf("apply: %v", err)
	}
	// Roll back both migrations (latest first): [2, 1].
	reverted, err := Rollback(ctx, database, 2)
	if err != nil {
		t.Fatalf("rollback: %v", err)
	}
	if len(reverted) != 2 || reverted[0] != 2 || reverted[1] != 1 {
		t.Fatalf("expected to revert [2 1], got %v", reverted)
	}
	if v, _ := CurrentVersion(ctx, database); v != 0 {
		t.Fatalf("version after rollback = %d; want 0", v)
	}
	var tableCount int
	if err := database.QueryRowContext(ctx,
		`SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name='worlds'`).Scan(&tableCount); err != nil {
		t.Fatalf("count: %v", err)
	}
	if tableCount != 0 {
		t.Fatalf("worlds table survived rollback")
	}
}

// Package entity defines world entities — the "everything is an entity"
// principle. A named thing of the world (an item, a substance, a landmark,
// a piece of lore) lives in the database with a short gist everyone knows
// and, once materialized, a backstory of its own. Knowledge about entities
// is modelled as links: who knows it, who owns it, where it sits, and which
// other entities its story mentions.
package entity

import (
	"fmt"
	"slices"
	"strings"
	"time"
	"unicode/utf8"

	"github.com/dnd-llm/dnd-llm/internal/domain"
)

// Kind classifies what sort of thing an entity is.
type Kind string

const (
	// KindItem is a concrete object or ware: a loaf of night-flour bread.
	KindItem Kind = "item"
	// KindSubstance is a material or ingredient: the night flour itself.
	KindSubstance Kind = "substance"
	// KindFeature is a natural or urban landmark: a river, a bell, a bridge.
	KindFeature Kind = "feature"
	// KindLore is an immaterial story: a legend, a custom, a past event.
	KindLore Kind = "lore"
)

// AllKinds returns every valid entity kind.
func AllKinds() []Kind {
	return []Kind{KindItem, KindSubstance, KindFeature, KindLore}
}

// IsValid reports whether the kind is one of the known values.
func (k Kind) IsValid() bool {
	switch k {
	case KindItem, KindSubstance, KindFeature, KindLore:
		return true
	}
	return false
}

// Carriable reports whether a thing can be carried off in BARE HANDS in a USEFUL
// amount — true only for a discrete solid object (an item). This is an engine-level
// fact of physical form, reused wherever the world moves a thing into someone's
// grasp (picking up, a fire means). The two bounds it encodes, both already in
// Kind:
//   - FORM (lower bound): a SUBSTANCE — a liquid, a powder, a flame — slips through
//     fingers. You can cup a trifle, but to carry any quantity you need a vessel.
//   - SIZE (upper bound): a FEATURE — a building, a river, a bell — is too large and
//     fixed to lift; LORE is immaterial.
//
// So «зачерпнуть воду руками» yields a handful at most and «унести таверну» is
// impossible by construction, not by a special case.
func (k Kind) Carriable() bool {
	return k == KindItem
}

// IsPhysical reports whether a thing of this kind has a BODY — item, substance or
// feature — as opposed to immaterial LORE (a legend, a custom). Only a physical
// thing carries physical properties (flammability, fracture mode), so this is the
// gate every minting author checks before recording them: a предание has no
// flammability, and asking for one is a category error.
func (k Kind) IsPhysical() bool {
	switch k {
	case KindItem, KindSubstance, KindFeature:
		return true
	}
	return false
}

// Lifecycle tracks how fleshed-out an entity is.
type Lifecycle string

const (
	// LifecycleStub is a named mention: the entity has a gist but no story
	// of its own yet. Asking about it triggers lazy materialization.
	LifecycleStub Lifecycle = "stub"
	// LifecycleMaterialized means the entity has a backstory and ways to
	// interact with it.
	LifecycleMaterialized Lifecycle = "materialized"
)

// Origin records who brought the entity into the world.
type Origin string

const (
	// OriginFixture marks authored content from the city seed.
	OriginFixture Origin = "fixture"
	// OriginMaterializer marks entities born as mentions during lazy
	// materialization of another entity's backstory.
	OriginMaterializer Origin = "materializer"
	// OriginScribe marks entities captured from NPC dialogue or narration.
	OriginScribe Origin = "scribe"
	// OriginWeaver marks entities introduced by the story weaver.
	OriginWeaver Origin = "weaver"
	// OriginCrystallized marks mundane items born "out of thin air" when the
	// player reached for something plausible that the scene did not list yet
	// (the common-sense gate said the place would have it).
	OriginCrystallized Origin = "crystallized"
)

// Category is a closed capability vocabulary for items. The deterministic
// verdict engine reads it instead of asking an LLM what a thing can do:
// fire ignites, weapons and tools break.
type Category string

// Category is the thing's ARTIFACT ROLE — what kind of made object it is and how it is
// used (a tool, a weapon, a garment, tableware). It deliberately carries NEITHER the
// elemental means a thing supplies (the source axis) NOR whether it can be INGESTED (the
// consumable axis below): both are orthogonal, because a thing can be an artifact AND,
// separately, a means or a foodstuff. A jug is a utensil that HOLDS a drink — it is not
// itself a drink (the «holds liquid» truth is the containment axis, the «is a beverage»
// truth the consumable axis). Mashing role, element and ingestibility into one mutually-
// exclusive label made the classifier choose one of several truths (a jug pulled toward
// «drink»); each axis now asks ONE question. One value, one question.
const (
	CategoryUtensil  Category = "utensil"
	CategoryTool     Category = "tool"
	CategoryWeapon   Category = "weapon"
	CategoryClothing Category = "clothing"
	CategoryMisc     Category = "misc"
)

// AllCategories returns every valid non-empty category.
func AllCategories() []Category {
	return []Category{
		CategoryUtensil, CategoryTool, CategoryWeapon, CategoryClothing, CategoryMisc,
	}
}

// Consumable axis: whether a thing can be INGESTED, and how — orthogonal to its artifact
// Category and its Containment. A loaf is eaten (food), ale is drunk (drink); the VESSEL
// that holds a drink is NOT itself a drink (it is a utensil with containment:сосуд,
// consumable none). The deterministic consume path reads this, never the category.
const (
	ConsumableFood  = "food"
	ConsumableDrink = "drink"
)

