// — the defensive twin of MartialForce. Only a true weapon is built to parry; a tool is
// improvised offence, not a guard. Feeds ViolenceContest.Guard.
func (c Category) ParryGuard() int {
	if c == CategoryWeapon {
		return 1
	}
	return 0
}

