// EntityState is the mutable side of an entity — a closed catalogue of ORTHOGONAL axes, each its
// own typed field (the json tags ARE the State* key constants, so the persisted shape and the SQL
// json_extract paths are unchanged). It replaced a map[string]any bag: a struct value is always
// usable (the zero value is "no axes set", so there are no nil guards) and every axis carries its
// real type — string modes, a []string tag list, uint64 onset ticks — instead of any.
type EntityState struct {
	Tags          []string `json:"tags,omitempty"`           // StateTags: authored membership labels
	Interactions  string   `json:"interactions,omitempty"`   // StateInteractions: how the world can act on it
	Condition     string   `json:"condition,omitempty"`      // StateCondition: current condition note
	RecentChanges string   `json:"recent_changes,omitempty"` // StateRecentChanges: rolling change journal
	Hazard        string   `json:"hazard,omitempty"`         // StateHazard: standing-hazard effect key
	HazardSince   uint64   `json:"hazard_since,omitempty"`   // StateHazardSince: tick the hazard took hold
	Thermal       string   `json:"thermal,omitempty"`        // StateThermal: heat-response mode
	Moisture      string   `json:"moisture,omitempty"`       // StateMoisture: wet/dry marker
	MoistureSince uint64   `json:"moisture_since,omitempty"` // StateMoistureSince: tick it became wet
	Consumable    string   `json:"consumable,omitempty"`     // StateConsumable: ingestion mode
	Source        string   `json:"source,omitempty"`         // StateSource: elemental means supplied
	Containment   string   `json:"containment,omitempty"`    // StateContainment: liquid-holding form
	Content       string   `json:"content,omitempty"`        // StateContent: full/empty marker
	ContentKind   string   `json:"content_kind,omitempty"`   // StateContentKind: which liquid a vessel holds
	Fracture      string   `json:"fracture,omitempty"`       // StateFracture: how it yields to force
	Integrity     string   `json:"integrity,omitempty"`      // StateIntegrity: structural-condition token
}

// recentChangesRunes caps the rolling change journal so a long-lived entity's recorded history
// can't grow without bound in its persisted state.
const recentChangesRunes = 240

// RecordCondition sets the entity's current condition note and appends it to the rolling
// recent-changes journal (capped at recentChangesRunes). The two always move together —
// recording a new condition IS a recent change — so callers never touch the two keys apart.
func (e *Entity) RecordCondition(note string) {
	e.State.Condition = note
	e.State.RecentChanges = appendChange(e.StateText(StateRecentChanges), note)
}

// appendChange appends note to the rolling journal, trimming the oldest entries once the
// combined length passes recentChangesRunes.
func appendChange(log, note string) string {
	if log == "" {
		return note
	}
	combined := log + "; " + note
	if utf8.RuneCountInString(combined) <= recentChangesRunes {
		return combined
	}
	r := []rune(combined)
	return strings.TrimLeft(string(r[len(r)-recentChangesRunes:]), "; ")
}

// SetHazard marks the entity a STANDING hazard of the given effect, stamping WHEN the hazard took
// hold so the tick can burn it out after a fixed span. The stamp is set ONCE (a re-applied hazard
// never resets the clock). A no-op for any non-hazard effect, so a bad key never pins a fake threat
// (mirrors SetSource/SetConsumable self-guarding on their closed vocab).
func (e *Entity) SetHazard(effect string, tick domain.Tick) {
	if !IsHazardEffect(effect) {
		return
	}
	e.State.Hazard = effect
	if _, ok := e.HazardSince(); !ok {
		if tick.IsZero() {
			tick = 1
		}
		e.State.HazardSince = uint64(tick)
	}
}

// ClearHazard ends a standing hazard — the thing stops burning, spreading and flooring fear. A
// no-op on a thing that is not a hazard.
func (e *Entity) ClearHazard() {
	e.State.Hazard = ""
	e.State.HazardSince = 0
}

// SetInteractions records how the world can interact with the entity (authored at
// materialization). Empty input leaves it unset.
func (e *Entity) SetInteractions(v string) {
	if v == "" {
		return
	}
	e.State.Interactions = v
}

// StateText returns the string-valued axis named by a State* key, or "" when that axis is unset.
// It reads the typed EntityState fields — the string key is a closed-vocabulary selector over the
// catalogue, not a free map lookup (an unknown key yields "").
func (e *Entity) StateText(key string) string {
	switch key {
	case StateInteractions:
		return e.State.Interactions
	case StateCondition:
		return e.State.Condition
	case StateRecentChanges:
		return e.State.RecentChanges
	case StateHazard:
		return e.State.Hazard
	case StateThermal:
		return e.State.Thermal
	case StateMoisture:
		return e.State.Moisture
	case StateConsumable:
		return e.State.Consumable
	case StateSource:
		return e.State.Source
	case StateContainment:
		return e.State.Containment
	case StateContent:
		return e.State.Content
	case StateContentKind:
		return e.State.ContentKind
	case StateFracture:
		return e.State.Fracture
	case StateIntegrity:
		return e.State.Integrity
	}
	return ""
}

// Tags returns the authored membership labels. The typed []string field round-trips through the
// typed state column as []string (no more []any degradation that the old map[string]any forced).
func (e *Entity) Tags() []string {
	return e.State.Tags
}

// HasTag reports whether the entity carries the given StateTags entry.
func (e *Entity) HasTag(tag string) bool {
	return slices.Contains(e.Tags(), tag)
}

