// Post-processes the kubb-generated operation types to replace the one `any` kubb leaves behind.
//
// kubb types each operation's error as `export type <Op>Error = ErrorModel` (from the OpenAPI
// `default` error response), but the operation aggregate type `<Op>Query`/`<Op>Mutation` hardcodes
// `Errors: any` — kubb does not wire a `default`-only error into that field. The field is unused by
// the app and the client functions, but it is still `any` in the codebase. This wires it to the
// already-generated, typed `<Op>Error`, so the generated client carries zero `any`.
//
// Runs as part of `generate:api` (after kubb), so it survives every regeneration.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const typesDir = join(dirname(fileURLToPath(import.meta.url)), '..', 'app', 'api', 'generated', 'types')

let patched = 0
let unresolved = 0
for (const file of readdirSync(typesDir).filter((f) => f.endsWith('.ts'))) {
  const path = join(typesDir, file)
  let src = readFileSync(path, 'utf8')
  if (!src.includes('Errors: any')) continue

  // The error type kubb generated for this operation, e.g. `export type GetPlayStatusError = ...`.
  const errorType = src.match(/export type (\w+Error) =/)?.[1]
  if (!errorType) {
    unresolved++
    continue
  }
  const next = src.replaceAll('Errors: any;', `Errors: ${errorType};`)
  if (next !== src) {
    writeFileSync(path, next)
    patched++
  }
}

// kubb's internal FormData helper types its recursive value as `any`; every branch narrows it
