package extraction

import (
	"context"
	"fmt"
	"strings"

	"github.com/dnd-llm/dnd-llm/internal/domain"
	domllm "github.com/dnd-llm/dnd-llm/internal/domain/llm"
	infrallm "github.com/dnd-llm/dnd-llm/internal/infrastructure/llm"
	"github.com/dnd-llm/dnd-llm/internal/infrastructure/search"
	"github.com/google/uuid"
)

// Stage 1 of the player-turn pipeline: ground a free-text mention («кузнец»,
// «кабак») in a real entity ID. Two tiers, cheap first:
//
//  1. Deterministic: the search cascade over names and authored aliases
//     (exact/fuzzy/substring, then vector). A confident single hit resolves
//     without any LLM call.
//  2. Semantic: a grammar-framed LLM grounding over SCOPED candidates — the
//     model knows «кабак» is a tavern, and the dynamic enum makes choosing a
//     nonexistent entity impossible. Candidate scope (co-located actors, the
//     city's locations) is bounded by the player's situation, not the world's
//     size, so this scales to arbitrarily large worlds.
//
// Anything still unmatched comes back ungrounded and turns into a clarifying
// question — never a guess.

// groundingAcceptScore is the deterministic-tier acceptance bar: name/alias
// matches at or above it (exact alias = 1.0) resolve without the LLM.
const groundingAcceptScore = 0.9

// groundingNoMatch is the sentinel the grounding model picks when no candidate
// fits the mention. It must stay distinguishable from any plausible entity name.
const groundingNoMatch = "никто из перечисленных"

// MentionKind tells the resolver what the mention refers to.
type MentionKind string

const (
	MentionWho   MentionKind = "who"
	MentionWhere MentionKind = "where"
	// MentionWhat grounds mentions of world entities — things, substances,
	// landmarks, lore («хлеб из ночной муки», «река»).
	MentionWhat MentionKind = "what"
)

// Candidate is one entity the mention may refer to, with a short note that
// lets the grounding model reason semantically («Лунный Брод — таверна…»).
//
// Forms are the case-folded surface forms by which this entity may be NAMED in
// free text — authored aliases plus the declined word-forms the morph engine
// generates from its name. They feed ONLY the structural accelerator (scopeAccelerate),
// never the semantic enum: the model still chooses by the nominative Name, so the
// enum stays small, while the accelerator can short-circuit a declined name («Дароя»
// → Дарой) without a model call. Empty until the builder enriches it.
type Candidate struct {
	ID    string
	Name  string
	Note  string
	Forms []string
}

// Resolution is the outcome of grounding one mention.
type Resolution struct {
	ID   string
	Name string
	// Grounded is false when neither tier could attach the mention to an
	// entity; the caller turns that into a clarifying question.
	Grounded bool
}

// MentionResolver grounds free-text mentions in world entities.
type MentionResolver struct {
	searcher *search.EntitySearcher
	llm      infrallm.SchemaCompleter
}

// NewMentionResolver builds a MentionResolver.
func NewMentionResolver(searcher *search.EntitySearcher, completer infrallm.SchemaCompleter) *MentionResolver {
	return &MentionResolver{searcher: searcher, llm: completer}
}

// Resolve grounds one mention. candidates is the situational scope (co-located
// actors for who, the city's locations for where) and feeds the grounding enum
// in full — the scope itself is what bounds it, not an arbitrary top-k.
func (r *MentionResolver) Resolve(
	ctx context.Context,
	worldID domain.WorldID,
	mention string,
	kind MentionKind,
	candidates []Candidate,
) (*Resolution, error) {
	mention = strings.TrimSpace(mention)
	if mention == "" {
		return &Resolution{}, nil
	}

	// Tier 1: deterministic search over names and authored aliases.
	if res := r.searchTier(ctx, worldID, mention, kind); res != nil {
		return res, nil
	}

	// Tier 2: semantic grounding over the scoped candidates.
	if len(candidates) == 0 {
		return &Resolution{}, nil
	}
	return r.groundingTier(ctx, mention, kind, candidates)
}

// searchTier runs the cascading entity search and accepts only a confident,
// unambiguous hit. Ambiguity (a close runner-up that is a different entity)
// falls through to the semantic tier rather than silently picking a winner.
func (r *MentionResolver) searchTier(ctx context.Context, worldID domain.WorldID, mention string, kind MentionKind) *Resolution {
	wid, err := uuid.Parse(string(worldID))
	if err != nil {
		return nil
	}

	resp, err := r.searcher.Search(ctx, search.SearchRequest{
		Query:       mention,
		WorldID:     &wid,
		EntityTypes: kind.searchTypes(),
		MaxResults:  3,
	})
	if err != nil || len(resp.Results) == 0 {
		return nil
	}
	// Accept ONLY a semantic VECTOR hit. Fuzzy (Levenshtein) and substring are LETTER-matching — the
	// word-matching crutch that mis-grounded «Уговор»→river_true_cause and made the GROUP path bypass the
	// fuzzy index; the single path was its dirty twin. When vector finds nothing the cascade falls to those
	// tiers (CascadeOnNoResult); reject them so the mention drops to the semantic groundingTier (the model
	// over the scope), never a letter collision. Grounding matches MEANING, not spelling.
	if resp.Method != domllm.MatchVector {
		return nil
	}

	top := resp.Results[0]
	if float64(top.Score) < groundingAcceptScore {
		return nil
	}
	if len(resp.Results) > 1 {
		runnerUp := resp.Results[1]
		if runnerUp.Entity.ID != top.Entity.ID && float64(runnerUp.Score) >= groundingAcceptScore {
			return nil // two confident, different entities → let semantics decide
		}
	}
	return &Resolution{ID: top.Entity.ID, Name: top.Entity.Name, Grounded: true}
}

func (k MentionKind) searchTypes() []domllm.SearchableType {
	switch k {
	case MentionWho:
		return []domllm.SearchableType{domllm.TypeActor}
	case MentionWhere:
		return []domllm.SearchableType{domllm.TypeLocation}
	case MentionWhat:
		return []domllm.SearchableType{domllm.TypeItem, domllm.TypeFeature, domllm.TypeLore}
	default:
		return nil
	}
}

// groundingSchema is the grammar frame for semantic grounding: match is a
// dynamic enum of candidate names plus the no-match sentinel, so the model
// physically cannot invent an entity.
type groundingSchema struct {
	Match string `json:"match"`
}

// groupSchema is the grammar frame for GROUP grounding: matches is an array
// whose every element is grammar-constrained to the candidate names — the
// model picks a SUBSET (empty = nobody), and inventing a person stays
// physically impossible.
type groupSchema struct {
	Matches []string `json:"matches"`
}

// ResolveGroup grounds a mention that may denote SEVERAL of the candidates at
// once: a description («сидящие за столом», «стражники»), a compound («приметы и
// Уговор») or a single name — which simply comes back as a one-element group. The
// structural accelerator resolves a clean, unique name (even declined) without any
// model call; otherwise the grammar-framed subset choice (GroupPerceive) reads the
// whole mention over the scoped candidates, whose notes carry each one's gist so
// descriptions and compounds can land on EVERY entity they denote. An empty result
// means the mention grounded in nobody.
//
// Unlike the single Resolve, this path does NOT consult the global search index: a
// fuzzy ≥0.9 index hit silently collapses a compound phrase to one approximate
// winner (the «Уговор → river_true_cause» mis-ground). The scope already carries the
// present∪knowledge entities, so the accelerator works scope-locally and any
// non-exact mention defers to the model — which can choose the SUBSET, not one.
func (r *MentionResolver) ResolveGroup(
	ctx context.Context,
	worldID domain.WorldID,
	mention string,
	kind MentionKind,
	candidates []Candidate,
) ([]Resolution, error) {
	mention = strings.TrimSpace(mention)
	if mention == "" {
		return nil, nil
	}
	if len(candidates) == 0 {
		return nil, nil
	}

	// The SEMANTIC tier is the SOLE authority: it gets the candidates and decides which the player
	// means — or NONE. No word-matching short-circuit ahead of it: scopeAccelerate force-grounded
	// «золотой кубок С алтаря» to «Камешек С площади» on the shared preposition «с» (a confabulated
	// take). Matching meaning, not letters, is the model's job — never a stem/substring collision.
	// (For a LARGE candidate set, embedding cosine RECALLS the relevant subset for this tier; the
	// scope here is already small — the location fund + present entities — so the model judges it whole.)
	names, err := GroupPerceive(ctx, r.llm, mention, kind, candidates)
	if err != nil {
		return nil, fmt.Errorf("ground group mention %q: %w", mention, err)
	}

	byName := make(map[string]Candidate, len(candidates))
	for _, c := range candidates {
		if _, dup := byName[c.Name]; !dup {
			byName[c.Name] = c
		}
	}
	var out []Resolution
	seen := map[string]bool{}
	for _, name := range names {
		c, ok := byName[name]
		if !ok || seen[c.ID] {
			continue
		}
		seen[c.ID] = true
		out = append(out, Resolution{ID: c.ID, Name: c.Name, Grounded: true})
	}
	return out, nil
}

// GroupPerceive is the SEMANTIC half of group grounding, factored out so the bench
// drives the exact production layer (no drifting copy): given a mention and the
// scoped candidates, a grammar-framed subset choice over their nominative names
// returns EVERY candidate the mention denotes (empty = nobody). The enum makes
// inventing an entity physically impossible; the model picks by meaning, so number
// (one or several) and morphology (case) fall out of comprehension, not surface
// matching. Returns the chosen candidate NAMES, deduplicated and filtered to valid
// candidates.
func GroupPerceive(
	ctx context.Context,
	llm infrallm.SchemaCompleter,
	mention string,
	kind MentionKind,
	candidates []Candidate,
) ([]string, error) {
	valid := make(map[string]bool, len(candidates))
	enum := make([]string, 0, len(candidates))
	var listing strings.Builder
	for _, c := range candidates {
		if valid[c.Name] {
			continue
		}
		valid[c.Name] = true
		enum = append(enum, c.Name)
		if c.Note != "" {
			fmt.Fprintf(&listing, "- %s — %s\n", c.Name, c.Note)
		} else {
			fmt.Fprintf(&listing, "- %s\n", c.Name)
		}
	}

	subject := "персонажей"
	if kind == MentionWhat {
		subject = "вещей и понятий"
	}
	userPrompt := fmt.Sprintf(`Игрок упомянул: «%s».

Список %s:
%s
Перечисли КАЖДОГО из списка, кто подходит под упоминание по смыслу — одного, нескольких или никого (тогда пустой список). Верни JSON.`,
		mention, subject, listing.String())

	request := infrallm.Request{
		SystemPrompt: "Ты сопоставляешь упоминание из речи игрока с сущностями игрового мира. Сопоставляй ТОЛЬКО по смыслу: роль, занятие, описание, падежная форма имени той же сущности. НЕ сопоставляй разные слова лишь по созвучию или похожему написанию имени. Сущность подходит, ТОЛЬКО если она и ЕСТЬ упомянутое — та же личность, вещь или понятие. НЕ включай сущность лишь за СВЯЗЬ с упоминанием: за то, что её описание говорит о нём, что она принадлежит ему, посвящена ему или находится рядом. Если ни одна сущность не ЕСТЬ упомянутое — верни пустой список, не подбирай ближайшую по смыслу. Упоминание-роль во множественном числе охватывает КАЖДОГО, кто ей соответствует.",
		UserPrompt:   userPrompt,
		Temperature:  0.1,
		MaxTokens:    128,
		Language:     "ru",
		Options: &infrallm.RequestOptions{
			DynamicEnums: map[string][]string{"matches": enum},
		},
	}

	schema, _, err := infrallm.Decode[groupSchema](ctx, llm, request)
	if err != nil {
		return nil, err
	}

	var out []string
	seen := map[string]bool{}
	for _, name := range schema.Matches {
		if !valid[name] || seen[name] {
			continue
		}
		seen[name] = true
		out = append(out, name)
	}
	return out, nil
}

// ResolveAccel grounds a mention using ONLY the structural accelerator — no model. For
// fields where a NAMED entity must match but a fuzzy SEMANTIC association must NOT: a
// thing-topic like «хлеб» must not ground to the baker it relates to, yet a named
// person-topic «про Дароя» must still land. The accelerator gives exactly that — it
// matches the entity's own name-forms, never an association.
func (r *MentionResolver) ResolveAccel(mention string, kind MentionKind, candidates []Candidate) []Resolution {
	if strings.TrimSpace(mention) == "" {
		return nil
	}
	return scopeAccelerate(mention, candidates)
}

// scopeAccelerate is the structural, model-free fast path: when the mention as a
// WHOLE is an exact (case-folded) match for the name, an authored alias, or a
// declined form of EXACTLY ONE candidate, that candidate resolves without the model.
// Any ambiguity (the form fits two different candidates) or a non-exact/compound
// mention yields nothing — the semantic tier decides.
//
// This is identity resolution by the entity's OWN forms — a closed paradigm the
// morph engine generated from its name, not a hand-kept word list — so it cannot
// drift and never silently picks an approximate winner (the honesty rule that keeps
// «Уговор» out of river_true_cause). The morph границу holds: Go matches a structural
// KEY (the entity's generated forms), it does not read the raw player text for
// meaning — that stays the model's job above.
func scopeAccelerate(mention string, candidates []Candidate) []Resolution {
	key := normalizeForm(mention)
	if key == "" {
		return nil
	}
	// 1) The mention as a WHOLE names a unique entity (a bare name, declined or not,
	//    or a surname word of a multi-word name). Whole-first so an embedded title
	//    («Капитан Дарой») resolves before its shared word («Капитан») can collide.
	if hit := uniqueMatch(candidates, []string{key}); hit != nil {
		return []Resolution{*hit}
	}
	// 2) A verb-laden or prepositioned phrase («про Дароя», «ищу Дароя на площади») the
	//    parser left un-isolated still NAMES an entity by one of its words. Scan the
	//    mention's tokens for a UNIQUE entity — so a person reference resolves
	//    deterministically, immune to scope size, instead of letting the model guess
	//    among a large enum. Two matching tokens (a compound «Дарой и Уговор») stay
	//    ambiguous and defer to the model, which returns the whole subset.
	if strings.ContainsRune(key, ' ') {
		if hit := uniqueMatch(candidates, strings.Fields(key)); hit != nil {
			return []Resolution{*hit}
		}
	}
	return nil
}

// uniqueMatch returns the single candidate named by any of keys, or nil when none or
// more than one match — the honesty rule that keeps the accelerator from guessing.
func uniqueMatch(candidates []Candidate, keys []string) *Resolution {
	var hit *Candidate
	for _, k := range keys {
		for i := range candidates {
			c := &candidates[i]
			if !candidateHasForm(c, k) {
				continue
			}
			if hit != nil && hit.ID != c.ID {
				return nil // two different entities matched → ambiguous, defer to the model
			}
			hit = c
		}
	}
	if hit == nil {
		return nil
	}
	return &Resolution{ID: hit.ID, Name: hit.Name, Grounded: true}
}

// candidateHasForm reports whether key (a normalized whole mention) names the
// candidate — as the WHOLE name/form, or, for a single-token mention, as one
// DISTINCTIVE word of a multi-word name/form. The latter lets a surname-only
// reference land: «Дароя» is a word of «Капитана Дароя» (the declined «Капитан
// Дарой»), so it matches even though the whole mention differs. Ambiguity (a word
// shared by two candidates, like a common title) is caught by scopeAccelerate, which
// then defers to the model — so word-matching never silently guesses.
func candidateHasForm(c *Candidate, key string) bool {
	if normalizeForm(c.Name) == key {
		return true
	}
	for _, f := range c.Forms {
		if normalizeForm(f) == key {
			return true
		}
	}
	if !strings.ContainsRune(key, ' ') {
		if hasWord(c.Name, key) {
			return true
		}
		for _, f := range c.Forms {
			if hasWord(f, key) {
				return true
			}
		}
	}
	return false
}

// hasWord reports whether key equals a word of phrase (both normalized). A
// single-token reference can thus name a multi-word entity by one of its words.
func hasWord(phrase, key string) bool {
	for _, w := range strings.Fields(normalizeForm(phrase)) {
		if w == key {
			return true
		}
	}
	return false
}

// normalizeForm case-folds a surface form for exact comparison (ё→е so the two
// spellings of one name collapse). Whitespace-trimmed; the accelerator matches a
// mention only as a WHOLE, so a multi-word compound never equals a single form.
func normalizeForm(s string) string {
	return strings.ReplaceAll(strings.ToLower(strings.TrimSpace(s)), "ё", "е")
}

// groundingTier asks the model which candidate the mention means. Names are
// deduplicated for the enum; the first occurrence wins (fixture names are
// unique in practice — a collision only narrows colour, not correctness).
func (r *MentionResolver) groundingTier(
	ctx context.Context,
	mention string,
	kind MentionKind,
	candidates []Candidate,
) (*Resolution, error) {
	byName := make(map[string]Candidate, len(candidates))
	enum := make([]string, 0, len(candidates)+1)
	var listing strings.Builder
	for _, c := range candidates {
		if _, dup := byName[c.Name]; dup {
			continue
		}
		byName[c.Name] = c
		enum = append(enum, c.Name)
		if c.Note != "" {
			fmt.Fprintf(&listing, "- %s — %s\n", c.Name, c.Note)
		} else {
			fmt.Fprintf(&listing, "- %s\n", c.Name)
		}
	}
	enum = append(enum, groundingNoMatch)

	subject := "персонажей"
	switch kind {
	case MentionWhere:
		subject = "мест"
	case MentionWhat:
		subject = "вещей и понятий"
	}
	userPrompt := fmt.Sprintf(`Игрок упомянул: «%s».

Список %s:
%s
Кого или что из списка игрок имеет в виду? Если ничего не подходит — выбери «%s». Верни JSON.`,
		mention, subject, listing.String(), groundingNoMatch)

	request := infrallm.Request{
		SystemPrompt: "Ты сопоставляешь упоминание из речи игрока с реальной сущностью игрового мира. Опирайся на смысл: профессии, прозвища, синонимы, описания.",
		UserPrompt:   userPrompt,
		Temperature:  0.1,
		MaxTokens:    96,
		Language:     "ru",
		Options: &infrallm.RequestOptions{
			DynamicEnums: map[string][]string{"match": enum},
		},
	}

	schema, _, err := infrallm.Decode[groundingSchema](ctx, r.llm, request)
	if err != nil {
		return nil, fmt.Errorf("ground mention %q: %w", mention, err)
	}

	c, ok := byName[schema.Match]
	if !ok { // sentinel
		return &Resolution{}, nil
	}
	return &Resolution{ID: c.ID, Name: c.Name, Grounded: true}, nil
}

package player

import (
	"context"
	"fmt"
	"strings"

	"github.com/dnd-llm/dnd-llm/internal/application/extraction"
	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/actor"
	"github.com/dnd-llm/dnd-llm/internal/domain/entity"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
	"go.uber.org/zap"
)

// The grounding pass runs ONCE per turn (groundTurn → MentionSet, with the structural
// accelerator and the experiential-field scope). Action handlers READ that result by
// the field text they hold — they never re-match raw player words. These accessors are
// the single consumption point, replacing the old per-handler stem matchers.

// groundedID returns the entity id `text` grounded to this turn for the given kind, or
// "" — read from the turn's one grounding pass, not re-matched.
func (tc *turnContext) groundedID(text string, kind extraction.MentionKind) string {
	if tc.mentions == nil {
		return ""
	}
	text = strings.TrimSpace(text)
	if text == "" {
		return ""
	}
	for _, m := range tc.mentions.Mentions {
		if m.Kind == kind && strings.EqualFold(strings.TrimSpace(m.Text), text) {
			return m.ID
		}
	}
	return ""
}

// groundedActor returns the roster actor `text` grounded to this turn (who-kind),
// excluding the given ids (a deed or topic about the speaker or the player themselves
// is not a reference to a third person).
func (tc *turnContext) groundedActor(text string, exclude ...domain.ActorID) *actor.Actor {
	id := tc.groundedID(text, extraction.MentionWho)
	if id == "" {
		return nil
	}
	aid := domain.ActorID(id)
	for _, ex := range exclude {
		if ex == aid {
			return nil
		}
	}
	return tc.actorByID(aid)
}

// groundedCoLocatedActor returns the grounded actor only when they stand HERE — the
// right scope for a DEED (you strike or embrace who is present, not someone you merely
// remember from elsewhere). References that need no presence (talking ABOUT a person)
// use groundedActor instead.
func (tc *turnContext) groundedCoLocatedActor(text string, exclude ...domain.ActorID) *actor.Actor {
	a := tc.groundedActor(text, exclude...)
	if a == nil || a.GetCurrentLocation() != tc.player.GetCurrentLocation() {
		return nil
	}
	return a
}

// topicNamesCurrentPlace reports whether a talk topic refers to the place the speaker
// stands in («спрашиваю про часовню», сидя в ней). Grounded by the resolver (the
// structural accelerator first) against the one current location — not a stem match.
func (s *TurnService) topicNamesCurrentPlace(ctx context.Context, tc *turnContext, topic string) bool {
	if s.resolver == nil || strings.TrimSpace(topic) == "" {
		return false
	}
	here := tc.player.GetCurrentLocation()
	loc, ok := tc.locations[here]
	if !ok {
		return false
	}
	cand := []extraction.Candidate{{
		ID:    string(here),
		Name:  loc.Name,
		Forms: s.candidateForms(loc.Name, nil),
	}}
	group, err := s.resolver.ResolveGroup(ctx, tc.worldID, topic, extraction.MentionWhere, cand)
	return err == nil && len(group) > 0
}

// groundedThing returns the experiential-field entity `text` grounded to this turn
// (what-kind), or nil.
func (tc *turnContext) groundedThing(text string) *entity.Entity {
	id := tc.groundedID(text, extraction.MentionWhat)
	if id == "" || tc.expField == nil {
		return nil
	}
	for _, e := range tc.expField.things {
		if string(e.ID) == id {
			return e
		}
	}
	return nil
}

// groundTurn is С2: ONE grounding pass over the turn's parsed deeds — every entity
// REFERENCE (who/where/target/instrument/topic) resolved to a real world id against a
// scope of present ∪ knowledge entities (memory candidates fold in next). The result,
// a MentionSet, is what lets story hooks fire by MEMBERSHIP and is journaled for
// replay. Additive for now: the action handlers still re-resolve what they execute on.
func (s *TurnService) groundTurn(ctx context.Context, tc *turnContext, actions []extraction.ParsedPlayerAction) *extraction.MentionSet {
	set := extraction.NewMentionSet()
	if s.resolver == nil {
		return set
	}
	// The candidate scope is the player's experiential field — here-now ∪ visited ∪
	// remembered ∪ known — assembled once for the turn, not just what is co-located.
	field := s.experientialField(ctx, tc)
	actorScope := s.actorCandidates(field.actors)
	locScope := s.locationCandidates(tc)
	thingScope := s.entityCandidates(field.things)

	// ground resolves one reference against a scope and records EVERY entity it denotes.
	// Set-valued perception (ResolveGroup): a compound reference («приметы и Уговор»)
	// grounds to all its entities, a declined name to the right one — the model reads
	// meaning, not surface form. Closed-vocab markers (the dialogue partner, "everyone")
	// are not world entities to bind — the addressee resolver handles them downstream —
	// so they are skipped here.
	ground := func(text string, kind extraction.MentionKind, scope []extraction.Candidate) bool {
		text = strings.TrimSpace(text)
		if text == "" ||
			strings.EqualFold(text, extraction.PartnerMention) ||
			strings.EqualFold(text, extraction.EveryoneMention) {
			return false
		}
		group, err := s.resolver.ResolveGroup(ctx, tc.worldID, text, kind, scope)
		if err != nil || len(group) == 0 {
			return false
		}
		for _, res := range group {
			set.Add(text, res.ID, kind)
		}
		return true
	}

	// groundAccel is the model-free variant: it grounds a reference against a scope by
	// the structural accelerator ONLY (a named entity, even declined or embedded in a
	// phrase), never the semantic model. Used where a fuzzy association would mislead —
	// a thing-topic «хлеб» must not ground to the baker it relates to.
	groundAccel := func(text string, kind extraction.MentionKind, scope []extraction.Candidate) bool {
		text = strings.TrimSpace(text)
		if text == "" ||
			strings.EqualFold(text, extraction.PartnerMention) ||
			strings.EqualFold(text, extraction.EveryoneMention) {
			return false
		}
		hits := s.resolver.ResolveAccel(text, kind, scope)
		for _, res := range hits {
			set.Add(text, res.ID, kind)
		}
		return len(hits) > 0
	}

	for _, a := range actions {
		ground(a.Who, extraction.MentionWho, actorScope)
		ground(a.Where, extraction.MentionWhere, locScope)
		ground(a.Instrument, extraction.MentionWhat, thingScope)
		// A Topic may be «про Дароя» (a person) as easily as «про воду» (a thing), and
		// the parser may leave a person embedded in a verb-laden topic («ищу Дароя на
		// площади»). For the PERSON pass use the accelerator ONLY: a NAMED person lands,
		// but a thing-topic never grounds to a person it merely relates to («хлеб» must
		// not become the baker). A thing falls through to the thing scope.
		if !groundAccel(a.Topic, extraction.MentionWho, actorScope) {
			ground(a.Topic, extraction.MentionWhat, thingScope)
		}
		// Target is what a deed ACTS ON — a person (often by role: «бью стражника»,
		// which needs the model) or a thing. People first, then things.
		if !ground(a.Target, extraction.MentionWho, actorScope) {
			ground(a.Target, extraction.MentionWhat, thingScope)
		}
	}
	if s.logger != nil {
		pairs := make([]string, 0, len(set.Mentions))
		for _, m := range set.Mentions {
			pairs = append(pairs, fmt.Sprintf("%s→%s[%s]", m.Text, m.ID, m.Kind))
		}
		s.logger.Debug("grounded mentions", zap.Int("n", set.Len()), zap.Strings("mentions", pairs))
	}
	return set
}

// recordMentions journals the turn's grounded MentionSet so the deterministic hooks
// are reproducible from the log (a replay reads the ids, never re-calls the LLM).
// Best-effort: a failed append only costs replay fidelity, never the turn.
func (s *TurnService) recordMentions(ctx context.Context, tc *turnContext) {
	if s.events == nil || tc.mentions == nil || tc.mentions.Len() == 0 {
		return
	}
	refs := make([]event.ResolvedMentionRef, 0, len(tc.mentions.Mentions))
	for _, m := range tc.mentions.Mentions {
		refs = append(refs, event.ResolvedMentionRef{Text: m.Text, ID: m.ID, Kind: string(m.Kind)})
	}
	evt := event.NewGameEvent(
		event.EventTypeMentionsResolved,
		tc.player.ID, tc.player.GetCurrentLocation(), tc.worldID, tc.tick,
		event.MentionsResolvedEventData{PlayerID: tc.player.ID, Tick: tc.tick, Mentions: refs},
	)
	if err := s.events.Append(ctx, evt); err != nil {
		s.logger.Debug("record mentions failed", zap.Error(err))
		return
	}
	s.logger.Debug("mentions grounded", zap.Int("n", tc.mentions.Len()))
}

// entityCandidates projects the experiential field's things into grounding
// candidates: each carries its gist as the note so a descriptive reference can land,
// and its declined forms + aliases for the structural accelerator. Deduplicated by id.
func (s *TurnService) entityCandidates(things []*entity.Entity) []extraction.Candidate {
	seen := map[string]struct{}{}
	out := make([]extraction.Candidate, 0, len(things))
	for _, e := range things {
		id := string(e.ID)
		if id == "" {
			continue
		}
		if _, dup := seen[id]; dup {
			continue
		}
		seen[id] = struct{}{}
		out = append(out, extraction.Candidate{
			ID:    id,
			Name:  e.Name,
			Note:  truncateRunes(e.Gist, 80),
			Forms: s.candidateForms(e.Name, e.Aliases),
		})
	}
	return out
}

// candidateForms assembles the structural match-keys for a grounding candidate: the
// declined word-forms the morph engine generates from its name PLUS authored aliases.
// These feed the model-free accelerator (scopeAccelerate) so a name in any case
// resolves without a model call. Nil-safe: no morph, or a paradigm not yet warmed,
// degrades to just the aliases (a cold name warms in the background for next time),
// and the accelerator simply defers that mention to the semantic tier.
func (s *TurnService) candidateForms(name string, aliases []string) []string {
	forms := append([]string(nil), aliases...)
	if s.morph == nil {
		return forms
	}
	if infl := s.morph.Inflections(name); len(infl) > 0 {
		return append(forms, infl...)
	}
	s.morph.WarmAsync(name)
	return forms
}

