// ── L4 set-perception: a free-text reference → the SET of scope entities it denotes ──
//
// groundset drives the PRODUCTION ENTRY POINT MentionResolver.ResolveGroup (not the inner
// GroupPerceive tier) — the grammar-framed subset choice the turn grounding leans on. It probes
// the two seams the coverage measure exposed: a CASE-DECLINED name must still ground by meaning
// (morphology-agnostic), and a COMPOUND phrase must ground to EVERY entity it names (cardinality),
// not collapse to one approximate winner. Plus false friends (a capitalized common word that is no
// entity) and zero-match (the empty set, not a guess). Cases are held-out from the prompt.
//
// WHY the ENTRY POINT, not the tier: a GroupPerceive-only bench was structurally BLIND to the
// scopeAccelerate word-match short-circuit that ran AHEAD of it in ResolveGroup and force-matched
// «золотой кубок С алтаря»→«Камешек С площади» on the shared preposition «с» (a confabulated take) —
// green bench over a broken path. Driving ResolveGroup (nil searcher → it grounds through the
// semantic tier only) means any short-circuit re-added ahead of the tier is caught HERE, not just in
// production. (ResolveAccel still uses scopeAccelerate — its own orchestration still wants a harness.)

type groundSetCase struct {
	mention string
	kind    extraction.MentionKind
	scope   []extraction.Candidate
	want    []string // expected candidate names, as a SET
}

var groundSetCases = []groundSetCase{
	// DECLENSION — the model must read case and land the nominative entity.
	{"Дароя", extraction.MentionWho, []extraction.Candidate{
		{ID: "1", Name: "Дарой", Note: "капитан стражи"},
		{ID: "2", Name: "Мирра", Note: "служанка в таверне"},
		{ID: "3", Name: "Бром", Note: "лодочник у переправы"},
	}, []string{"Дарой"}},
	{"Дароем", extraction.MentionWho, []extraction.Candidate{
		{ID: "1", Name: "Дарой", Note: "капитан стражи"},
		{ID: "2", Name: "Изольт", Note: "торговец на площади"},
	}, []string{"Дарой"}},

	// COMPOUND — a phrase that names TWO entities must ground to BOTH.
	{"речные приметы и Уговор", extraction.MentionWhat, []extraction.Candidate{
		{ID: "1", Name: "Речные приметы", Note: "молва о знаках замерзающей реки"},
		{ID: "2", Name: "Уговор", Note: "древний договор горожан с рекой"},
		{ID: "3", Name: "Старый Колокол", Note: "треснувший колокол на площади"},
	}, []string{"Речные приметы", "Уговор"}},

	// MULTI-ENTITY description — a plural role names every matching person.
	{"стражники", extraction.MentionWho, []extraction.Candidate{
		{ID: "1", Name: "Хем", Note: "стражник на южных воротах"},
		{ID: "2", Name: "Горан", Note: "стражник в казарме"},
		{ID: "3", Name: "Мирра", Note: "служанка в таверне"},
	}, []string{"Хем", "Горан"}},

	// DESCRIPTION by past event — note carries the deed, the model reads it.
	{"та, что плакала у колодца", extraction.MentionWho, []extraction.Candidate{
		{ID: "1", Name: "Мирра", Note: "служанка, плакала у колодца этим утром"},
		{ID: "2", Name: "Вель", Note: "хозяин таверны"},
		{ID: "3", Name: "Лис", Note: "вор с рынка"},
	}, []string{"Мирра"}},

	// DESCRIPTION by gist — a thing named by what it is.
	{"река", extraction.MentionWhat, []extraction.Candidate{
		{ID: "1", Name: "Тихвод", Note: "река, что течёт через город"},
		{ID: "2", Name: "Уговор", Note: "древний договор горожан с рекой"},
	}, []string{"Тихвод"}},

	// FALSE FRIEND — a capitalized common word that is NO entity here. (Note: a name
	// ONE letter off, like «Гром»→«Бром», is intentionally NOT tested — the system's
	// own Levenshtein tier treats that as typo-tolerance, so it is ambiguous, not a
	// clean false friend. The honest probe is a semantically unrelated word.)
	{"Ярмарка", extraction.MentionWho, []extraction.Candidate{
		{ID: "1", Name: "Бром", Note: "кузнец у горна"},
		{ID: "2", Name: "Дарой", Note: "капитан стражи"},
		{ID: "3", Name: "Мирра", Note: "служанка в таверне"},
	}, nil},

	// ZERO-MATCH — nothing in scope; the empty set, not a nearest guess.
	{"дракон", extraction.MentionWho, []extraction.Candidate{
		{ID: "1", Name: "Бром", Note: "кузнец у горна"},
		{ID: "2", Name: "Дарой", Note: "капитан стражи"},
	}, nil},
	{"звёздная карта", extraction.MentionWhat, []extraction.Candidate{
		{ID: "1", Name: "Уговор", Note: "древний договор горожан с рекой"},
		{ID: "2", Name: "Старый Колокол", Note: "треснувший колокол на площади"},
	}, nil},

	// FALSE FRIEND by CATEGORY — a same-CLASS but DIFFERENT object (a «golden goblet» / «sharp
	// sword» is NOT the pebble / debt-book / mug that ARE here). The model must pick no-match, NOT
	// force the nearest small thing. Live (логи): «золотой кубок» force-grounded to «Камешек с
	// площади» → crystallize tried a PEBBLE for a goblet → confabulated take. Harder than the
	// semantically-distant дракон/звёздная карта: both ends are small physical props.
	{"золотой кубок", extraction.MentionWhat, []extraction.Candidate{
		{ID: "1", Name: "Камешек с площади", Note: "гладкий камешек, поднятый с мостовой"},
		{ID: "2", Name: "Старый Колокол", Note: "треснувший колокол на площади"},
	}, nil},
	{"острый меч", extraction.MentionWhat, []extraction.Candidate{
		{ID: "1", Name: "Долговая книга", Note: "потёртая книга записей в таверне"},
		{ID: "2", Name: "Кружка эля", Note: "глиняная кружка с элем"},
	}, nil},

	// SINGLE EXACT — the control: one name, one hit.
	{"Уговор", extraction.MentionWhat, []extraction.Candidate{
		{ID: "1", Name: "Уговор", Note: "древний договор горожан с рекой"},
		{ID: "2", Name: "Тихвод", Note: "река, что течёт через город"},
	}, []string{"Уговор"}},

	// PERSON INSIDE A PHRASE (who-kind) — the parser sometimes leaves a person
	// reference embedded in a verb-laden topic («ищу Дароя на площади», «про Дароя»)
	// instead of a bare name. Grounding a topic against PEOPLE must still pull the
	// named person out, so a person-topic lands on the actor, not a thing.
	{"ищу Дароя на площади", extraction.MentionWho, []extraction.Candidate{
		{ID: "1", Name: "Капитан Дарой", Note: "капитан стражи"},
		{ID: "2", Name: "Орин", Note: "стражник"},
		{ID: "3", Name: "Пекарка Анна", Note: "пекарка"},
	}, []string{"Капитан Дарой"}},
	{"про Дароя", extraction.MentionWho, []extraction.Candidate{
		{ID: "1", Name: "Капитан Дарой", Note: "капитан стражи"},
		{ID: "2", Name: "Мирра", Note: "служанка"},
	}, []string{"Капитан Дарой"}},

	// A thing-topic must NOT false-match a person when grounded against PEOPLE.
	{"осматриваю воду у причала", extraction.MentionWho, []extraction.Candidate{
		{ID: "1", Name: "Капитан Дарой", Note: "капитан стражи"},
		{ID: "2", Name: "Орин", Note: "стражник"},
	}, nil},

	// HEAD-NOUN of a COMPOUND thing-name — «острогу» (accusative of the head) must reach «Острога
	// Грома» (a thing named with its OWNER in the genitive). The mention names the THING; the owner
	// rides along in the name. Mirror of «Дароя»→«Капитан Дарой» on the thing axis (e2e seam: buying
	// «острогу» bounced «здесь не видно такого»).
	{"острогу", extraction.MentionWhat, []extraction.Candidate{
		{ID: "1", Name: "Острога Грома", Note: "рыбацкая острога, ею бьют ночную рыбу"},
		{ID: "2", Name: "Кружка эля", Note: "глиняная кружка тёмного эля"},
	}, []string{"Острога Грома"}},
	{"невод", extraction.MentionWhat, []extraction.Candidate{
		{ID: "1", Name: "Невод Грома", Note: "рыбацкая сеть перевозчика"},
		{ID: "2", Name: "Краюха хлеба", Note: "ломоть ржаного хлеба"},
	}, []string{"Невод Грома"}},
}

func runGroundSet(ctx context.Context, p infrallm.SchemaCompleter, samples int) {
	resolver := extraction.NewMentionResolver(nil, p) // nil searcher: ResolveGroup grounds via the semantic tier only
	pass, total := 0, 0
	for i, c := range groundSetCases {
		fmt.Printf("\n%s\n#%-2d хотим {%s}\n   упоминание: «%s» [%s]\n%s\n",
			strings.Repeat("═", 90), i+1, strings.Join(sortedSet(c.want), ", "),
			c.mention, c.kind, strings.Repeat("─", 90))
		for s := 1; s <= samples; s++ {
			res, err := resolver.ResolveGroup(ctx, domain.WorldID("bench"), c.mention, c.kind, c.scope)
			if err != nil {
				fmt.Printf("  ⃟%d ✗ %v\n", s, err)
				total++
				continue
			}
			got := make([]string, 0, len(res))
			for _, r := range res {
				got = append(got, r.Name)
			}
			mark := "✗"
			if sameSet(got, c.want) {
				mark = "✓"
				pass++
			}
			total++
			fmt.Printf("  ⃟%d  {%s}  %s\n", s, strings.Join(sortedSet(got), ", "), mark)
		}
	}
	fmt.Printf("\n%s\nИТОГ groundset: ✓=%d ✗=%d из %d\n", strings.Repeat("═", 90), pass, total-pass, total)
}

func sortedSet(xs []string) []string {
	out := append([]string(nil), xs...)
	sort.Strings(out)
	return out
}

func sameSet(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	sa, sb := sortedSet(a), sortedSet(b)
	for i := range sa {
		if sa[i] != sb[i] {
			return false
		}
	}
	return true
}

