package extraction

import (
	"context"
	"fmt"
	"strings"

	infrallm "github.com/dnd-llm/dnd-llm/internal/infrastructure/llm"
)

// Layered input perception (see CLAUDE.md «Слоистое восприятие»). The player-turn
// parser is a STACK of narrow grammar-bound LLM passes, each doing ONE thing —
// reliable on a 4B precisely because it does not mix ontological types. The
// domain-tuned core (segment → extractAction → ParsedPlayerAction, in
// intent_parser.go) stays; THIS file holds the layers that AUGMENT it — capabilities
// the flat parser never had, validated in cmd/benches/parser and now the single source
// of truth (the bench imports these):
//
//   L1 discourse — normalize the player's own revisions + tell action from query.
//   L3 modality  — the deed's envelope (polarity + mood), seen over the WHOLE utterance.
//   L5 state     — the player's EXPLICIT emotion, fed to the actor model (not the action path).
//
// Agency (commanded/joint) and reference grounding belong to L4 (= MentionResolver);
// they are not here.

// ── L1: discourse — normalize the raw utterance before deed segmentation ──────

// Discourse is L1's output: the utterance's communicative type, plus the normalized
// action text once the player's revisions (cancellations, reorder) are resolved.
type Discourse struct {
	// Type is "action" (the player does something in the world) or "query" (the
	// player asks a question — answered by the GM, not executed).
	Type string `json:"type" enum:"action,query"`
	// Normalized is, for an action, the FINAL intended sequence after the player's
	// revisions; for a query, the question itself.
	Normalized string `json:"normalized" maxlen:"200"`
}

const discoursePrompt = `Дано сырое сообщение игрока. Нормализуй его ДО разбора действий. JSON {"type":"...","normalized":"..."}.
- type: action — игрок ЧТО-ТО ДЕЛАЕТ в мире, ВКЛЮЧАЯ РАЗГОВОР: спросить/сказать ПЕРСОНАЖУ (обращение к кому-то в мире) — это действие. Сюда же — НАМЕРЕННОЕ БЕЗДЕЙСТВИЕ (переждать, выждать, коротать время, бездействовать): игрок ДЕЙСТВУЕТ, решив дать времени течь, — это action, не query (он не спрашивает ГМ, а пережидает). query — игрок СПРАШИВАЕТ ГМ о мире/состоянии/правилах, НИ К КОМУ в мире не обращаясь (что/где/кто/сколько ЗДЕСЬ…), хочет узнать, а не действовать. Вопрос, ОБРАЩЁННЫЙ К ПЕРСОНАЖУ (спрашиваю/спросить у кого-то), — это action (разговор), НЕ query.
- normalized: для action — итоговая последовательность действий ПОСЛЕ правок игрока. Учти отмены и переупорядочивание: «нет», «стоп», «вместо этого», «хотя нет» отменяют сказанное ранее; «сначала», «сперва» переставляют порядок. Для query — сам вопрос.
- ВАЖНО: правь ТОЛЬКО если в сообщении ЕСТЬ слова-правки (нет/стоп/сначала/сперва/вместо/хотя нет). Если правок НЕТ — верни normalized = сообщение игрока ДОСЛОВНО, без изменений: не переписывай, не сокращай, не выбрасывай части (отрицание «не …», условие «если …» — оставь как есть).
Слова бери у игрока, не выдумывай.`

// NormalizeDiscourse runs L1: classify action-vs-query and resolve the player's own
// revisions into a clean action utterance for the segmenter downstream.
func NormalizeDiscourse(ctx context.Context, c infrallm.SchemaCompleter, utterance string) (Discourse, error) {
	req := infrallm.Request{
		SystemPrompt: discoursePrompt,
		UserPrompt:   fmt.Sprintf("Сообщение игрока: «%s»\n\nОпредели тип и нормализуй. Верни JSON.", utterance),
		Temperature:  0.1,
		MaxTokens:    200,
		Language:     "ru",
	}
	d, _, err := infrallm.Decode[Discourse](ctx, c, req)
	return d, err
}

// ── L3: modality — the deed's envelope (polarity + mood) ──────────────────────

// DeedModality is L3's output: how a deed relates to actualisation. Operators over a
// deed only — polarity (refrain) + mood (actual/conditional/attempt/feigned). Agency
// (commanded/joint) is L4, not here. Trigger holds the condition text iff conditional.
type DeedModality struct {
	Modality string `json:"modality" enum:"actual,refrain,conditional,attempt,feigned"`
	Trigger  string `json:"trigger" maxlen:"80"`
}

// ModalityActual is the default — the deed simply happens. A blank modality coerces to it.
const ModalityActual = "actual"

const modalityPrompt = `Дано сообщение игрока и ОДНО его деяние. Определи МОДАЛЬНОСТЬ именно ЭТОГО деяния. JSON {"modality":"...","trigger":"..."}.

По умолчанию деяние — actual. Меняй ТОЛЬКО при ЯВНОМ маркере, относящемся К ЭТОМУ деянию:
- refrain — при ЭТОМ деянии стоит отрицание «не» («не трогаю …»): игрок воздерживается.
- conditional — ЭТО деяние не происходит сразу: оно СРАБОТАЕТ, лишь когда наступит названное событие-триггер. Триггер вводит придаточное-зачин: «если», «когда», «пока», «как только», «едва», «чуть», «стоит … как», «раз» — и любой подобный оборот со смыслом «в момент/при условии, что …». Распознавай по СМЫСЛУ (деяние ждёт события), а не по списку слов. В trigger впиши это условие словами из сообщения. ВНИМАНИЕ: «чтобы …» — это ЦЕЛЬ деяния (зачем), а НЕ триггер; деяние с «чтобы» — actual.
- attempt — ТОЛЬКО при ЯВНОМ маркере усилия с неясным исходом: «пытаюсь», «силюсь», «стараюсь», «норовлю», «тщусь». Без такого слова деяние НЕ attempt — даже если глагол длительный или незавершённый (тяну, нажимаю, иду): само по себе оно actual, а под триггером-зачином — conditional.
- feigned — при ЭТОМ деянии «притворяюсь», «делаю вид»: не на самом деле.
- actual — НИ ОДНОГО из этих маркеров при этом деянии нет; игрок просто это делает. Обычное действие (беру, бью, иду) — actual, НЕ attempt.

Маркер относится к тому деянию, при глаголе которого он стоит. Если при ЭТОМ деянии своего маркера НЕТ — оно actual, даже если у СОСЕДНЕГО деяния в реплике маркер есть. «только», «лишь», «просто» перед деянием — акцент, НЕ модальность. trigger пустой, если не conditional; в trigger бери слова из сообщения дословно, не выдумывай.`

// DetectModality runs L3 for one deed, seeing the WHOLE utterance (a condition or
// negation often sits outside the deed's own words). Returns actual by default.
func DetectModality(ctx context.Context, c infrallm.SchemaCompleter, utterance, deed string) (DeedModality, error) {
	req := infrallm.Request{
		SystemPrompt: modalityPrompt,
		UserPrompt:   fmt.Sprintf("Сообщение: «%s»\nДеяние: «%s»\n\nОпредели модальность деяния. Верни JSON.", utterance, deed),
		Temperature:  0.1,
		MaxTokens:    120,
		Language:     "ru",
	}
	m, _, err := infrallm.Decode[DeedModality](ctx, c, req)
	if strings.TrimSpace(m.Modality) == "" {
		m.Modality = ModalityActual
	}
	return m, err
}

// ── Lc: manner — is THIS deed performed covertly (by stealth)? ────────────────

// covertResult is the manner probe's grammar frame: a single bool envelope, same
// shape philosophy as L3 modality. The monolithic extract, juggling ten other
// fields, under-reads stealth (bench: «тихонько»/«незаметно» came out false);
// pulled into its own focused pass it reads both the explicit marker and the
// circumstantial stealth, and rejects the false friend (a quiet mood ≠ a covert
// take). Grammar-bound bool, default false.
type covertResult struct {
	Covert bool `json:"covert"`
}

const covertPrompt = `Дано сообщение игрока и ОДНО его деяние. Совершается ли ЭТО деяние СКРЫТНО — украдкой, чтобы не заметили? JSON {"covert":true|false}.
- covert=true — деяние спрятано от окружающих: явный наречный признак скрытности (тихо, незаметно, крадучись, украдкой, исподтишка, втихаря, скрытно) ЛИБО обстоятельство, прячущее деяние от чужих глаз (внимание отвлечено, никто не смотрит, со спины).
- covert=false — деяние на виду, открыто; признака скрытности нет. «Тихо» о настроении или покое — это НЕ скрытность.
Опирайся на слова игрока. Сомневаешься — false.`

// DetectCovert runs the manner probe for one deed, seeing the WHOLE utterance (a
// stealth circumstance often sits outside the deed's own words). Returns false on
// any doubt — the safe default the consumers (theft stealth-contest) expect.
func DetectCovert(ctx context.Context, c infrallm.SchemaCompleter, utterance, deed string) (bool, error) {
	req := infrallm.Request{
		SystemPrompt: covertPrompt,
		UserPrompt:   fmt.Sprintf("Сообщение: «%s»\nДеяние: «%s»\n\nСкрытно ли деяние? Верни JSON.", utterance, deed),
		Temperature:  0.1,
		MaxTokens:    20,
		Language:     "ru",
	}
	r, _, err := infrallm.Decode[covertResult](ctx, c, req)
	return r.Covert, err
}

// ── Lp: terms — what price did the player name for this transfer? ─────────────

// paymentResult is the terms probe's grammar frame: the price the player named,
// verbatim, or empty. Extract under-reads it (bench: «за три медяка» → empty) while
// busy with the deed; the narrow pass also rejects the false friend «за» (by/behind/
// for-a-reason is not a price).
type paymentResult struct {
	Payment string `json:"payment" maxlen:"40"`
}

const paymentPrompt = `Дано сообщение игрока и ОДНО его деяние — игрок что-то берёт или отдаёт. Назвал ли игрок ЦЕНУ — плату, во что обходится обмен? JSON {"payment":"..."}.
- payment — названная игроком плата ДОСЛОВНО: сколько денег или какая вещь идёт в обмен. Бери слова игрока.
- payment="" — цена не названа: берёт или даёт даром. ВАЖНО: предлог «за» — НЕ всегда плата: он же вводит место/направление, способ хватки, причину — это НЕ цена, payment пустой. Плата — только когда «за» (или «в обмен на») вводит то, что отдают ВЗАМЕН.`

// DetectPayment runs the terms probe for one transfer deed. Returns the named price
// verbatim, or empty when none was named.
func DetectPayment(ctx context.Context, c infrallm.SchemaCompleter, utterance, deed string) (string, error) {
	req := infrallm.Request{
		SystemPrompt: paymentPrompt,
		UserPrompt:   fmt.Sprintf("Сообщение: «%s»\nДеяние: «%s»\n\nКакая цена названа? Верни JSON.", utterance, deed),
		Temperature:  0.1,
		MaxTokens:    40,
		Language:     "ru",
	}
	r, _, err := infrallm.Decode[paymentResult](ctx, c, req)
	return strings.TrimSpace(r.Payment), err
}

// ── Ld: tempo — how long the deed plausibly takes (the duration envelope) ─────

// durationResult is the tempo probe's grammar frame: one closed bucket. Duration is an
// ENVELOPE of the deed (its tempo), the same ontological shape as modality (mood),
// covert (manner) and payment (terms) — and like them it under-reads in the crowded
// extract: the punctual buckets (миг/секунды/минута) come out fine, but the DURATIVE
// «долго» (a deed that runs UNTIL an event, or sweeps a whole scope) gets mistaken for a
// short physical span. Pulled into its own focused pass — seeing the whole utterance —
// the durative reads reliably AND the extract loses a field. The enum mirrors the closed
// catalogue (duration.go) exactly.
type durationResult struct {
	Duration string `json:"duration" enum:"миг,секунды,минута,долго"`
}

const durationPrompt = `Дано сообщение игрока и ОДНО его деяние. Оцени, СКОЛЬКО ВРЕМЕНИ деяние занимает в мире. JSON {"duration":"..."}.
Выбери ОДИН бакет:
- "миг" — ОДИН взрывной миг: удар, бросок, рывок, окрик. Деяние кончается в то же мгновение, как началось.
- "секунды" — коротко, но НЕ мгновенно: достать/поднять вещь, бросить взгляд, короткая фраза. Есть длительность в пару ударов сердца.
- "минута" — затяжное разовое: дойти до другого места, тщательно обыскать одного, вскарабкаться.
- "долго" — ДЛИТЕЛЬНОЕ, тянущееся: деяние продолжается, ПОКА не наступит событие (сторожить/ждать, пока кого-то не сменят) ЛИБО охватывает всё целиком (обшарить весь чердак, латать парус часами).
ВАЖНО: «долго» — про саму ПРОТЯЖЁННОСТЬ деяния во времени, НЕ про предлог «до». «Дотронуться до плеча», «дойти до колодца» — это НЕ долго: «до» тут вводит цель/направление, а само деяние быстрое.`

// DetectDuration runs the tempo probe for one deed, seeing the whole utterance (the
// end-condition that makes a deed durative often sits outside the deed's own words).
// Coerces to a known bucket so the round packer can always pace the turn.
func DetectDuration(ctx context.Context, c infrallm.SchemaCompleter, utterance, deed string) (string, error) {
	req := infrallm.Request{
		SystemPrompt: durationPrompt,
		UserPrompt:   fmt.Sprintf("Сообщение: «%s»\nДеяние: «%s»\n\nСколько времени занимает деяние? Верни JSON.", utterance, deed),
		Temperature:  0.1,
		MaxTokens:    16,
		Language:     "ru",
	}
	r, _, err := infrallm.Decode[durationResult](ctx, c, req)
	return NormalizeDuration(r.Duration), err
}

// ── Lw: wait span — until which phase of day a deliberate wait runs ───────────

// waitSpanResult is the wait-span probe's frame: a closed target phase-of-day, or empty
// when the player names no span (a plain wait advances the default hour). The phases
// mirror the day's named bands (time.go GetTimeOfDay); the wait handler turns the choice
// into a fast-forward to that phase's onset, so «жду до утра» skips to morning rather
// than passing a fixed hour. Its own focused pass (like Ld duration), gated on a wait deed.
type waitSpanResult struct {
	Until string `json:"until" enum:"ничего,рассвет,утро,полдень,вечер,ночь"`
}

const waitSpanPrompt = `Игрок пережидает время. НАЗВАЛ ли он, до какой ПОРЫ СУТОК ждёт? JSON {"until":"..."}.
ПО УМОЛЧАНИЮ — "ничего": чаще всего игрок просто пережидает, НЕ называя поры суток («жду немного», «выжидаю», «коротаю время») → "ничего".
Выбери пору ТОЛЬКО если игрок ЯВНО указал, ДО какого времени суток он ждёт:
- "рассвет" — ждёт, пока ночь не кончится и не начнёт светать (до зари, до восхода солнца, до первого света).
- "утро" — ждёт, пока не настанет утро, не проснётся город, не наступит светлый день.
- "полдень" — ждёт до полудня, до середины дня.
- "вечер" — ждёт, пока день не склонится к вечеру, не спадёт дневной зной.
- "ночь" — ждёт, пока не стемнеет, не наступит глубокая ночь.
ВАЖНО: пора-ЦЕЛЬ — это «до УТРА», «до ВЕЧЕРА» (время суток), а НЕ «до края причала» (место) и не «до удобного мига» (не пора). И пора-ПРИЛАГАТЕЛЬНОЕ при существительном («идёт вечерней улицей», «дышит утренним туманом», «под ночным дождём») — ОПИСАНИЕ картины, а НЕ цель: оно говорит, КАКОВ предмет, а не ДО чего игрок ждёт. Цель — лишь явное «жду ДО [поры]» / «пока не настанет [пора]». Нет такого → "ничего".`

// DetectWaitSpan classifies the phase-of-day a deliberate wait runs until (closed enum),
// or "" when the player named no span. Seeing the whole utterance — the span sits outside
// the bare «жду». Mirror of DetectDuration; the caller gates it on a wait deed.
func DetectWaitSpan(ctx context.Context, c infrallm.SchemaCompleter, utterance string) (string, error) {
	req := infrallm.Request{
		SystemPrompt: waitSpanPrompt,
		UserPrompt:   fmt.Sprintf("Сообщение: «%s»\n\nДо какой поры суток игрок пережидает? Верни JSON.", utterance),
		Temperature:  0.1,
		MaxTokens:    16,
		Language:     "ru",
	}
	r, _, err := infrallm.Decode[waitSpanResult](ctx, c, req)
	until := strings.TrimSpace(r.Until)
	if until == "ничего" { // the «no span named» sentinel maps to empty (default-hour wait)
		until = ""
	}
	return until, err
}

// ── Lm: money target — does a covert take reach for COINS, not a thing ────────

// moneyTargetResult is the money-target probe's frame: is the lift aimed at the holder's MONEY
// (a purse, coins) rather than a discrete item? Money is not an entity (it is the actor's Wealth
// scalar), so a covert take of coins can never ground a thing — the handler routes a «да» to the
// pickpocket path (a wealth lift through the same stealth contest) instead of «здесь нет такого».
type moneyTargetResult struct {
	Money string `json:"money" enum:"да,нет"`
}

const moneyTargetPrompt = `Игрок СКРЫТНО тянется к чужому. Целит ли он в ДЕНЬГИ как таковые — кошель, мошну, монеты, выручку, казну, — а НЕ в конкретный ПРЕДМЕТ? JSON {"money":"да|нет"}.
- "да" — крадёт ЧУЖИЕ деньги: срезать кошель, вытащить монеты, очистить мошну, увести выручку.
- "нет" — целит в конкретную ВЕЩЬ (оружие, утварь, снедь, украшение, свёрток) — пусть и ценную, но не деньги.`

// DetectMoneyTarget reports whether a covert take reaches for the holder's MONEY (vs a discrete
// item). Mirror of DetectWaitSpan; the caller gates it on a covert take deed. Defaults to false.
func DetectMoneyTarget(ctx context.Context, c infrallm.SchemaCompleter, mention string) (bool, error) {
	req := infrallm.Request{
		SystemPrompt: moneyTargetPrompt,
		UserPrompt:   fmt.Sprintf("Скрытное деяние: «%s»\n\nЦель — деньги или конкретная вещь? Верни JSON.", mention),
		Temperature:  0.1,
		MaxTokens:    16,
		Language:     "ru",
	}
	r, _, err := infrallm.Decode[moneyTargetResult](ctx, c, req)
	return strings.TrimSpace(r.Money) == "да", err
}

// ── Lg: coin gift — how many coins the player HANDS OVER (give path) ──────────

// coinGiftResult is the coin-gift probe's frame: the number of coins the player gives a
// counterpart. Money is the Wealth scalar, not an entity, so a coins-gift can never ground a
// thing — the give handler reads this count to move wealth instead of bouncing «здесь нет такого».
// 0 = the give is a discrete THING (or money with no number), not a coin handover.
type coinGiftResult struct {
	Coins int `json:"coins"`
}



