ifySpeechAct(ctx context.Context, c infrallm.SchemaCompleter, utterance string, inConv bool, affordances []string) (SpeechAct, error) {
	user := fmt.Sprintf("Сообщение игрока: «%s»\n\nОпредели: речь это или физическое действие. Верни JSON.", utterance)
	if inConv {
