	req := infrallm.Request{
		SystemPrompt: speechPrompt,
		UserPrompt:   user,
		Temperature:  0.1,
		MaxTokens:    240,
		Language:     "ru",
		Options:      &infrallm.RequestOptions{DynamicEnums: map[string][]string{"kind": kinds}},
	}
	sa, _, err := infrallm.Decode[SpeechAct](ctx, c, req)
	if strings.TrimSpace(sa.Kind) == "" {
		sa.Kind = SpeechDeed
	}
	return sa, err
}

// ── L5: state — the player's emotion (classify) + its strip (normalize) ───────
//
// State is L5's ontological type, handled by TWO focused passes. Folding both into one
// call overloaded the 4B and tanked emotion accuracy (benched: горе→отвращение,
// цепенею→удивление) while the strip stayed clean — the model vskрывает шов: classifying a
// feeling (enum) and rewriting the utterance (text) are different operations and must not
// share a call (the same lesson as the monolithic extract). They run concurrently (~one
// call's latency), each doing ONE thing:
//   · DetectState — name the explicit emotion (enum) → the actor model.
//   · StripState  — peel the state expression off, leaving the deed remainder → L2, so the
//     segmenter never sees state (an involuntary feeling-verb «холодею от страха» would
//     otherwise be cut as a phantom deed). Empty remainder = state ONLY, no deed.

// StateCalm is the default emotion label when none is explicitly expressed.
const StateCalm = "спокойствие"

// stateResult is the emotion classifier's grammar frame. The enum mirrors the domain basic
// emotions (domain/actor/emotional.go) in Russian; the caller maps the label to an
// actor.EmotionType.
type stateResult struct {
	Emotion string `json:"emotion" enum:"радость,печаль,гнев,страх,удивление,отвращение,спокойствие"`
}

const emotionPrompt = `Дано сообщение игрока. Определи ЭМОЦИОНАЛЬНОЕ состояние игрока, ЯВНО выраженное в сообщении. JSON {"emotion":"..."}.
Опирайся ТОЛЬКО на явное: слово-чувство («в восторге», «в унынии», «в бешенстве») или телесный признак чувства («кулаки стиснуты», «ноги подкосились», «побледнел»).
- радость / печаль / гнев / страх / удивление / отвращение / спокойствие.
НЕ выводи эмоцию из самого действия: удар — НЕ гнев, бегство — НЕ всегда страх. Если чувство НЕ выражено явно — спокойствие.
Тёплая или вежливая ОКРАСКА обычного обращения — это МАНЕРА (КАК сделано), а НЕ заявленное чувство: felt-эмоцию даёт лишь слово-чувство или телесный признак, не душевность тона. Обычное обращение с тёплой манерой — спокойствие.`

// DetectState runs L5's emotion classifier: read the player's EXPLICIT emotion (a feeling
// word or bodily sign), never inferred from the action itself. The parallel channel into
// the actor model. Returns a Russian emotion label.
func DetectState(ctx context.Context, c infrallm.SchemaCompleter, utterance string) (string, error) {
	req := infrallm.Request{
		SystemPrompt: emotionPrompt,
		UserPrompt:   fmt.Sprintf("Сообщение игрока: «%s»\n\nОпредели эмоцию. Верни JSON.", utterance),
		Temperature:  0.1,
		MaxTokens:    40,
		Language:     "ru",
	}
	s, _, err := infrallm.Decode[stateResult](ctx, c, req)
	if strings.TrimSpace(s.Emotion) == "" {
		return StateCalm, err
	}
	return s.Emotion, err
}

// strippedState is the strip pass's grammar frame: the utterance with the state expression
// removed, leaving only deeds. Empty = the utterance was state ONLY (no deed).
type strippedState struct {
	Deeds string `json:"deeds" maxlen:"200"`
}

const stripStatePrompt = `Дано сырое сообщение игрока. Убери из него ВЫРАЖЕНИЕ СОСТОЯНИЯ — переживание, обращённое на СЕБЯ — и верни только ДЕЯНИЯ. JSON {"deeds":"..."}.
Грань — КУДА обращено: ВНУТРЬ, на себя (состояние, УБЕРИ) или ВОВНЕ / это ВЫБОР игрока (деяние, ОСТАВЬ дословно, в том же порядке).
- Состояние (УБЕРИ) = ВНУТРЕННЕЕ, на СЕБЯ: чувство (слово-чувство), непроизвольная реакция тела (кулаки стиснуты, дух перехватило, оторопь берёт) — ПРОИСХОДИТ помимо воли; и борьба С СОБОЙ, попытка совладать с чувством (сдерживаю гнев, глотаю слёзы) — наружу при этом НИЧЕГО не сделано.
- Деяние = ВОВНЕ или ВЫБОР игрока: на мир/предмет (беру, бью, иду); ОБРАЩЕНИЕ к другому человеку (извиниться перед кем-то, окликнуть, поздравить) — несёт чувство, но это деяние, ведь ты ОБРАЩАЕШЬСЯ к другому, а не переживаешь в себе; и намеренное пропускание времени, когда игрок РЕШИЛ ничего не предпринимать и дать времени течь — это его ВЫБОР-деяние, не переживание. ОСТАВЬ дословно.
- ОТРИЦАНИЕ — это ТОЖЕ деяние: «не делаю X» («не открываю сундук») — намеренное воздержание, игрок так РЕШИЛ. ОСТАВЬ его ЦЕЛИКОМ дословно, даже если рядом стоит другое деяние, не выбрасывай. Отказ — НЕ состояние.
- Состояния в сообщении НЕТ — верни deeds ДОСЛОВНО равным сообщению, ничего не трогая.
- ОНО ЦЕЛИКОМ обращено на себя (только переживание или борьба с собой, наружу ничего) — deeds пустой.
Слова бери у игрока, деяния не перефразируй и ничего не добавляй.`

// StripState runs L5's normalizer: peel the state expression off the utterance, returning
// the deed remainder for the segmenter (L2 never sees state). Empty means the utterance was
// pure state with no deed (a state-only turn). On any doubt it leaves the deed verbatim.
func StripState(ctx context.Context, c infrallm.SchemaCompleter, utterance string) (string, error) {
	req := infrallm.Request{
		SystemPrompt: stripStatePrompt,
		UserPrompt:   fmt.Sprintf("Сообщение игрока: «%s»\n\nУбери состояние, оставь деяния. Верни JSON.", utterance),
		Temperature:  0.1,
		MaxTokens:    200,
		Language:     "ru",
	}
	s, _, err := infrallm.Decode[strippedState](ctx, c, req)
	return strings.TrimSpace(s.Deeds), err
}

// Command parserbench is ONE harness for the layered input parser (see CLAUDE.md
// «Слоистое восприятие»). Each layer is benched by a subcommand, in isolation, so a
// human can judge it without the noise of the others:
//
//	parserbench segment    # L2: cut an utterance into physical deeds
//	parserbench modality   # L3: (utterance, deed) → modality envelope
//	parserbench covert     # Lc: (utterance, deed) → covert (manner) envelope
//	parserbench payment    # Lp: (utterance, deed) → payment (terms) envelope
//	parserbench speech     # Ls: utterance → speech act (statement/question/trade/deed) + addressee
//	parserbench full       # L2 → L1.5 enrich → roles + L3 modality, end to end
//	parserbench pipeline   # ONE boundary message through the WHOLE stack (real ParseTraced) — fired/bypassed per layer
//	parserbench domain     # whole Parse, scored per domain field (integration regress)
//	parserbench cue        # CueClassifier.DeedEngages: deed → front lead cue (да/нет)
//	parserbench advgoal    # CueClassifier.DeedAdvancesGoal: deed → advances NPC goal (да/нет)
//	parserbench effect     # EffectSelector.Classify: deed → closed effect catalogue key
//
// Flags: -url, -model, -timeout, -samples, -cat (segment only: filter by category).
//
// Usage: go run ./cmd/benches/parser segment -url http://localhost:18080
package main

import (
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"net/http"
	"os"
	"strings"
	"time"

	infrallm "github.com/dnd-llm/dnd-llm/internal/infrastructure/llm"
)

func main() {
	if len(os.Args) < 2 {
		fmt.Println("usage: parserbench <segment|modality|covert|payment|speech|pipeline|groundset|discourse|state|parse|domain> [flags]")
		os.Exit(2)
	}
	sub := os.Args[1]

	fs := flag.NewFlagSet(sub, flag.ExitOnError)
	url := fs.String("url", "http://localhost:18080", "vllm base URL (no /v1)")
	model := fs.String("model", "default", "model id (default → resolve from server)")
	timeout := fs.Duration("timeout", 90*time.Second, "per-request timeout")
	samples := fs.Int("samples", 3, "samples per case")
	only := fs.String("cat", "", "segment: run only this category (substring); empty = all")
	backend := fs.String("provider", "llamacpp", "LLM backend: llamacpp (GBNF via native /completion, the live target) | vllm (vllm-rust, structured_outputs.grammar)")
	_ = fs.Parse(os.Args[2:])

	if *model == "default" {
		if served, err := servedModelID(*url); err == nil && served != "" {
			*model = served
			fmt.Printf("model resolved from server: %s\n", served)
		}
	}

	// The harness benches whatever grammar-bound backend serves -url. Each provider
	// carries its OWN grammar transport (vllm-rust: structured_outputs.grammar;
	// llama.cpp: GBNF on native /completion) — both fed by the same
	// BuildGrammarFromSchema, so layer pass-rates stay apples-to-apples. The live
	// target moved to llama.cpp (2026-06-24), hence the default. MaxRetries(0): a
	// retry would mask a frame failure we want to measure.
	var provider infrallm.LLMProvider
	switch *backend {
	case "llamacpp":
		provider = infrallm.NewLlamaCppProvider(
			infrallm.WithLlamaCppBaseURL(*url),
			infrallm.WithLlamaCppModel(*model),
			infrallm.WithLlamaCppHTTPClient(&http.Client{Timeout: *timeout}),
			infrallm.WithLlamaCppMaxRetries(0),
		)
	case "vllm":
		provider = infrallm.NewVLLMProvider(
			infrallm.WithVLLMBaseURL(*url),
			infrallm.WithVLLMModel(*model),
			infrallm.WithVLLMHTTPClient(&http.Client{Timeout: *timeout}),
			infrallm.WithVLLMMaxRetries(0),
		)
	default:
		fmt.Printf("unknown -provider %q (use: llamacpp | vllm)\n", *backend)
		os.Exit(2)
	}

	ctx := context.Background()
	if err := provider.HealthCheck(ctx); err != nil {
		fmt.Printf("cannot reach %s: %v\n", *url, err)
		return
	}

	switch sub {
	case "segment":
		runSegment(ctx, provider, *samples, *only)
	case "feasibility":
		runFeasibility(ctx, provider, *samples)
	case "presence":
		runPresence(ctx, provider, *samples)
	case "modality":
		runModality(ctx, provider, *samples)
	case "pipeline":
		runPipeline(ctx, provider, *samples)
	case "discourse":
		runDiscourse(ctx, provider, *samples)
	case "state":
		runState(ctx, provider, *samples)
	case "parse":
		runParse(ctx, provider, *samples)
	case "groundset":
		runGroundSet(ctx, provider, *samples)
	case "covert":
		runCovert(ctx, provider, *samples)
	case "payment":
		runPayment(ctx, provider, *samples)
	case "waitspan":
		runWaitSpan(ctx, provider, *samples)
	case "moneytarget":
		runMoneyTarget(ctx, provider, *samples)
	case "coingift":
		runCoinGift(ctx, provider, *samples)
	case "coindemand":
		runCoinDemand(ctx, provider, *samples)
	case "speech":
		runSpeech(ctx, provider, *samples)
	case "duration":
		runDuration(ctx, provider, *samples)
	case "domain":
		runDomain(ctx, provider, *samples, *only)
	case "cue":
		runCue(ctx, provider, *samples)
	case "advgoal":
		runAdvGoal(ctx, provider, *samples)
	case "effect":
		runEffect(ctx, provider, *samples)
	case "effdomain":
		runEffectDomain(ctx, provider, *samples)
	case "influence":
		runInfluence(ctx, provider, *samples)
	case "violence":
		runViolence(ctx, provider, *samples)
	case "aid":
		runAid(ctx, provider, *samples)
	case "distraction":
		runDistraction(ctx, provider, *samples)
	case "socialmove":
		runSocialMove(ctx, provider, *samples)
	case "vow":
		runVow(ctx, provider, *samples)
	default:
		fmt.Printf("unknown subcommand %q (want segment|modality|pipeline|groundset|discourse|state|parse|covert|payment|speech|domain|cue|advgoal|effect|influence|violence|aid|distraction|socialmove|vow)\n", sub)
		os.Exit(2)
	}
}

func servedModelID(baseURL string) (string, error) {
	client := &http.Client{Timeout: 5 * time.Second}
	resp, err := client.Get(strings.TrimRight(baseURL, "/") + "/v1/models")
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	var payload struct {
		Data []struct {
			ID string `json:"id"`
		} `json:"data"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&payload); err != nil {
		return "", err
	}
	if len(payload.Data) == 0 {
		return "", fmt.Errorf("server reported no models")
	}
	return payload.Data[0].ID, nil
}

package main

import (
	"context"

	"github.com/dnd-llm/dnd-llm/internal/application/extraction"
	infrallm "github.com/dnd-llm/dnd-llm/internal/infrastructure/llm"
)

// Bench helpers driving PRODUCTION perception. The per-layer benches call extraction's REAL
// functions (one source of truth — the same code the parser runs): L1 discourse, L3 modality,
// L5 state, L2 segment all live in extraction (perception.go); the role frame, the full flow,
// and grounding are exercised through the REAL parser (domain / pipeline drive extraction.Parse
// / ParseTraced; the llm `entity/topic-grounding` probe drives the real MentionResolver.Resolve)
// — no drifting local copies. (Former `full` [a dead local role-prompt + un-wired enrich] and
// `ground` [a groundingTier drift-copy] benches were deleted — green-over-not-prod is false
// confidence. `ground`'s rich cases — past-relation, disambiguation — to migrate to the entity
// probe; see TODO.)

// segment drives the PRODUCTION segmenter (extraction.SegmentDeeds — the same core
// IntentParser.segment calls), so this bench measures the REAL L2 prompt, not a drifting
// local copy. The isolated L2 bench passes no conversation context (empty ParseContext).
func segment(ctx context.Context, c infrallm.SchemaCompleter, phrase string) ([]string, error) {
	frags, _, err := extraction.SegmentDeeds(ctx, c, phrase, extraction.ParseContext{})
	return frags, err
}

